function NewGraphFlow({ onClose, onCreate }) {
  // step / setStep / stepNames / canContinue were retained on the previous redesign
  // to keep diffs small. They're not referenced anywhere live; the dead {false && ...}
  // block in the body still mentions `step` but Babel strips that branch.
  var [industry, setIndustry] = useState(null);
  var [func, setFunc]         = useState(null);
  var [startId, setStartId]   = useState("__blank"); // matches the default "blank" startMode
  var [included, setIncluded] = useState({}); // entity name → boolean
  var [customEntities, setCustomEntities] = useState([]); // [{ name, desc, props:[] }]
  var [userPrompt, setUserPrompt] = useState("");
  var [contextAttachments, setContextAttachments] = useState([]);
  var [addingEntity, setAddingEntity]     = useState(false);
  var [newEntityName, setNewEntityName]   = useState("");
  var [newEntityDesc, setNewEntityDesc]   = useState("");
  var [graphName, setGraphName]       = useState("");
  var [graphDesc, setGraphDesc]       = useState("");
  var [environment, setEnvironment]   = useState("production");
  var [owner, setOwner]               = useState("morgan.lee");
  var [permsRead,  setPermsRead]      = useState([{ kind:"group", id:"everyone",       label:"Everyone in org" }]);
  var [permsWrite, setPermsWrite]     = useState([{ kind:"group", id:"data-platform",  label:"data-platform team" }]);
  var [permsAdmin, setPermsAdmin]     = useState([{ kind:"user",  id:"morgan.lee",     label:"Morgan Lee (you)" }]);

  // (stepNames removed — single-modal redesign doesn't use a stepper.)

  // Industry is the HARD filter when picked (Healthcare must never see Retail-only
  // blueprints). When only a function is picked, function is the hard filter.
  // Function affects RANKING (not visibility) when industry is the active filter.
  var suggestions = GRAPH_STARTING_POINTS.map(function(sp){
    var indMatch  = industry ? sp.industry.indexOf(industry) >= 0 : false;
    var funcMatch = func     ? sp.fn.indexOf(func)           >= 0 : false;
    var indAny    = sp.industry.indexOf("any") >= 0;
    var include;
    if (!industry && !func)      include = true;
    else if (industry)           include = indMatch || indAny;        // industry rules
    else                         include = funcMatch;                 // only function picked
    var score = (indMatch ? 3 : 0) + (funcMatch ? 2 : 0) + (indAny && industry ? 0.5 : 0);
    return include ? Object.assign({}, sp, { _score: score, _exactInd: indMatch, _exactFn: funcMatch }) : null;
  }).filter(Boolean).sort(function(a, b){ return b._score - a._score; });

  var picked = startId === "__blank" ? null : GRAPH_STARTING_POINTS.find(function(s){ return s.id === startId; });
  var includedFromBlueprint = picked ? picked.entities.filter(function(e){ return included[e] !== false; }) : [];
  var entitiesToInclude     = includedFromBlueprint.concat(customEntities.map(function(c){ return c.name; }));

  // (canContinue removed — single-modal redesign uses `canActivate` defined below.)

  function pickStart(id) {
    setStartId(id);
    setCustomEntities([]);
    var sp = GRAPH_STARTING_POINTS.find(function(s){ return s.id === id; });
    if (sp) {
      var inc = {};
      sp.entities.forEach(function(e){ inc[e] = true; });
      setIncluded(inc);
      if (!graphName) setGraphName(sp.name);
      if (!graphDesc) setGraphDesc(sp.desc);
    } else if (id === "__blank") {
      setIncluded({});
      if (!graphName) setGraphName("");
      if (!graphDesc) setGraphDesc("");
    }
  }

  function commitNewEntity() {
    var nm = newEntityName.trim();
    if (!nm) return;
    setCustomEntities(function(arr){ return arr.concat([{ name: nm, desc: newEntityDesc.trim() || "Custom entity added during setup.", props:[] }]); });
    setNewEntityName(""); setNewEntityDesc(""); setAddingEntity(false);
  }

  var inp = { border:"1px solid var(--line)", borderRadius:7, padding:"11px 13px", fontSize:13, fontFamily:"inherit", color:"var(--ink)", background:"var(--panel)", outline:"none", boxSizing:"border-box", width:"100%", boxShadow:"inset 0 1px 0 rgba(255,255,255,0.6)" };
  var lbl = { display:"block", fontFamily:"JetBrains Mono", fontSize:9.5, letterSpacing:"0.6px", color:"var(--ink-3)", textTransform:"uppercase", marginBottom:6 };

  // Mini SVG preview of the picked starting point's entities + edges
  function StartingPointPreview({ sp }) {
    if (!sp) {
      return (
        <div style={{ padding:"40px 12px", textAlign:"center", color:"var(--ink-3)", fontSize:11.5, fontStyle:"italic" }}>Blank canvas — nothing pre-defined</div>
      );
    }
    var W = 280, H = 180;
    var cx = W/2, cy = H/2;
    var n = sp.entities.length;
    var positioned = sp.entities.map(function(name, i){
      var a = (i / n) * Math.PI * 2 - Math.PI / 2;
      var r = Math.min(W, H) * 0.34;
      return { name: name, x: cx + Math.cos(a) * r, y: cy + Math.sin(a) * r };
    });
    var byName = {}; positioned.forEach(function(p){ byName[p.name] = p; });
    return (
      <svg width="100%" height={H} viewBox={"0 0 " + W + " " + H} preserveAspectRatio="xMidYMid meet">
        <g stroke={sp.accent} strokeOpacity="0.45" strokeWidth="0.8">
          {sp.edges.map(function(e, i){
            var a = byName[e[0]], b = byName[e[2]];
            if (!a || !b) return null;
            return <line key={i} x1={a.x} y1={a.y} x2={b.x} y2={b.y} />;
          })}
        </g>
        <g>
          {positioned.map(function(p, i){
            return (
              <g key={i}>
                <circle cx={p.x} cy={p.y} r="14" fill={sp.accent} fillOpacity="0.18" stroke={sp.accent} strokeWidth="1.2" />
                <text x={p.x} y={p.y + 26} textAnchor="middle" style={{ fontFamily:"JetBrains Mono", fontSize:"8.5px", fill:"var(--ink-2)" }}>{p.name.length > 14 ? p.name.slice(0, 12) + "…" : p.name}</text>
              </g>
            );
          })}
        </g>
      </svg>
    );
  }

  var DIRECTORY = [
    { kind:"group", id:"everyone",        label:"Everyone in org" },
    { kind:"group", id:"data-platform",   label:"data-platform team" },
    { kind:"group", id:"customer-ops",    label:"customer-ops team" },
    { kind:"group", id:"finance-ops",     label:"finance-ops team" },
    { kind:"group", id:"engineering",     label:"engineering team" },
    { kind:"group", id:"security",        label:"security team" },
    { kind:"user",  id:"morgan.lee",      label:"Morgan Lee" },
    { kind:"user",  id:"ramin.k",         label:"Ramin K" },
    { kind:"user",  id:"jordan.s",        label:"Jordan S" }
  ];

  function RichDropdown({ value, onChange, options, placeholder, kind }) {
    var [open, setOpen] = useState(false);
    var sel = options.find(function(o){ return o.id === value; });
    function tileBg(o){ return o.accent || (o.enterprise ? "var(--ink)" : "var(--ink-3)"); }
    function tileContent(o, sz){
      if (kind === "function") return <FunctionIcon id={o.id} size={Math.round(sz * 0.55)} />;
      if (kind === "industry") return <IndustryIcon id={o.id} size={Math.round(sz * 0.55)} />;
      return <span style={{ fontFamily:"JetBrains Mono", fontSize: sz <= 28 ? 10 : 11, fontWeight:700, letterSpacing:"0.5px" }}>{o.code}</span>;
    }
    return (
      <div style={{ position:"relative" }}>
        <button onClick={function(){ setOpen(function(o){ return !o; }); }}
          style={{ display:"flex", alignItems:"center", gap:12, width:"100%", padding:"12px 14px", border:"1px solid var(--line)", borderRadius:9, background:"var(--panel)", cursor:"pointer", fontFamily:"inherit", textAlign:"left", boxShadow:"inset 0 1px 0 rgba(255,255,255,0.6)" }}>
          {sel ? (
            <>
              <span style={{ width:34, height:34, borderRadius:7, background:tileBg(sel), color:"#fff", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>{tileContent(sel, 34)}</span>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontSize:14, fontWeight:600, color:"var(--ink)" }}>{sel.label}</div>
                <div style={{ fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-3)", marginTop:2, whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{sel.desc}</div>
              </div>
              {sel.enterprise && <span style={{ fontFamily:"JetBrains Mono", fontSize:9, padding:"2px 6px", borderRadius:4, background:"var(--ink)", color:"var(--bg-canvas)", fontWeight:700, letterSpacing:"0.5px" }}>ENTERPRISE</span>}
              <span style={{ color:"var(--ink-3)", fontSize:11, fontFamily:"JetBrains Mono" }}>▾</span>
            </>
          ) : (
            <>
              <span style={{ width:34, height:34, borderRadius:7, background:"var(--chip)", border:"1px dashed var(--line)", color:"var(--ink-4)", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"JetBrains Mono", fontSize:14, flexShrink:0 }}>+</span>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontSize:14, color:"var(--ink-3)" }}>{placeholder}</div>
                <div style={{ fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-4)", marginTop:2 }}>Click to choose</div>
              </div>
              <span style={{ color:"var(--ink-3)", fontSize:11, fontFamily:"JetBrains Mono" }}>▾</span>
            </>
          )}
        </button>
        {open && (
          <>
            <div style={{ position:"fixed", top:0, left:0, right:0, bottom:0, zIndex:99 }} onClick={function(){ setOpen(false); }} />
            <div style={{ position:"absolute", top:"calc(100% + 6px)", left:0, right:0, zIndex:100, background:"var(--panel)", border:"1px solid var(--line)", borderRadius:10, boxShadow:"0 14px 38px rgba(0,0,0,0.18)", padding:6, maxHeight:380, overflowY:"auto" }}>
              {options.map(function(o, i){
                var isSel = value === o.id;
                return (
                  <button key={o.id} onClick={function(){ onChange(o.id); setOpen(false); }}
                    style={{ display:"flex", alignItems:"center", gap:12, width:"100%", padding:"9px 12px", borderRadius:7, border:"none", background: isSel ? "var(--bg-canvas)" : "transparent", cursor:"pointer", fontFamily:"inherit", textAlign:"left", marginBottom: i < options.length-1 ? 2 : 0 }}
                    onMouseEnter={function(e){ if (!isSel) e.currentTarget.style.background = "var(--panel-2)"; }}
                    onMouseLeave={function(e){ if (!isSel) e.currentTarget.style.background = "transparent"; }}>
                    <span style={{ width:30, height:30, borderRadius:6, background:tileBg(o), color:"#fff", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>{tileContent(o, 30)}</span>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:7 }}>
                        <span style={{ fontSize:13, fontWeight:600, color:"var(--ink)" }}>{o.label}</span>
                        {o.enterprise && <span style={{ fontFamily:"JetBrains Mono", fontSize:8.5, padding:"1px 5px", borderRadius:3, background:"var(--ink)", color:"var(--bg-canvas)", fontWeight:700, letterSpacing:"0.5px" }}>ENTERPRISE</span>}
                      </div>
                      <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)", marginTop:2, lineHeight:1.4 }}>{o.desc}</div>
                    </div>
                    {isSel && <span style={{ color:"var(--green)", fontWeight:700, fontSize:13 }}>✓</span>}
                  </button>
                );
              })}
            </div>
          </>
        )}
      </div>
    );
  }

  // ── Single-modal redesign ───────────────────────────────────────────────────
  // Replaces the previous 3-step stepper. Everything that's needed to spin up
  // a graph lives in one scrollable form: name, description, starting-point
  // choice, and (when "from template" is picked) a search + filters row above
  // the template list.
  // Default to "blank" — the fast path. Users who want a template can toggle and
  // then advance via the "Choose template →" CTA in the footer.
  var [startMode, setStartMode] = useState("blank"); // "blank" | "template"
  var [templateQuery, setTemplateQuery] = useState("");
  // Two-view modal: "form" (name/desc/starting-point) and "template" (picker).
  var [view, setView] = useState("form");

  // Template list — apply text search on top of the industry / function filter
  // already computed in `suggestions`.
  var qLower = templateQuery.trim().toLowerCase();
  var visibleSuggestions = !qLower ? suggestions : suggestions.filter(function(sp){
    if (sp.name.toLowerCase().indexOf(qLower) >= 0) return true;
    if (sp.desc && sp.desc.toLowerCase().indexOf(qLower) >= 0) return true;
    if (sp.entities && sp.entities.some(function(e){ return e.toLowerCase().indexOf(qLower) >= 0; })) return true;
    return false;
  });

  var canActivate = graphName.trim().length >= 2 && (startMode === "blank" || (startId && startId !== "__blank"));

  // Helper — sync startId when toggling start mode so "Create graph" can rely on a
  // single value downstream without re-implementing branch logic.
  function chooseStartMode(m) {
    setStartMode(m);
    if (m === "blank") {
      setStartId("__blank");
      setIncluded({});
    } else if (startId === "__blank") {
      // Coming from blank → un-set so the user has to pick a template
      setStartId(null);
    }
  }

  // Inline dropdown styled like the rest of the form (used for industry + function).
  function FilterDropdown({ value, onChange, options, placeholder, openState }) {
    var [open, setOpen] = useState(false);
    var sel = options.find(function(o){ return o.id === value; });
    return (
      <div style={{ position:"relative" }}>
        <button onClick={function(){ setOpen(function(o){ return !o; }); }}
          style={{ display:"flex", alignItems:"center", gap:8, width:"100%", padding:"9px 12px", border:"1px solid var(--line)", borderRadius:7, background:"var(--panel)", cursor:"pointer", fontFamily:"inherit", textAlign:"left", boxSizing:"border-box", boxShadow:"inset 0 1px 0 rgba(255,255,255,0.6)" }}>
          <span style={{ flex:1, fontSize:13, color: sel ? "var(--ink)" : "var(--ink-3)", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{sel ? sel.label : placeholder}</span>
          {sel && <button onClick={function(e){ e.stopPropagation(); onChange(null); }} style={{ background:"none", border:"none", padding:0, color:"var(--ink-3)", cursor:"pointer", fontSize:14, lineHeight:1, marginRight:2 }}>×</button>}
          <span style={{ color:"var(--ink-3)", fontSize:10, fontFamily:"JetBrains Mono" }}>{open ? "▴" : "▾"}</span>
        </button>
        {open && (
          <>
            <div style={{ position:"fixed", top:0, left:0, right:0, bottom:0, zIndex:99 }} onClick={function(){ setOpen(false); }} />
            <div style={{ position:"absolute", top:"calc(100% + 6px)", left:0, right:0, zIndex:100, background:"var(--panel)", border:"1px solid var(--line)", borderRadius:9, boxShadow:"0 14px 38px rgba(0,0,0,0.18)", padding:5, maxHeight:340, overflowY:"auto" }}>
              {options.map(function(o){
                var isSel = value === o.id;
                return (
                  <button key={o.id} onClick={function(){ onChange(o.id); setOpen(false); }}
                    style={{ display:"flex", alignItems:"center", gap:8, width:"100%", padding:"7px 10px", borderRadius:6, border:"none", background: isSel ? "var(--bg-canvas)" : "transparent", cursor:"pointer", fontFamily:"inherit", textAlign:"left" }}
                    onMouseEnter={function(e){ if (!isSel) e.currentTarget.style.background = "var(--panel-2)"; }}
                    onMouseLeave={function(e){ if (!isSel) e.currentTarget.style.background = "transparent"; }}>
                    <span style={{ flex:1, fontSize:12.5, color:"var(--ink)" }}>{o.label}</span>
                    {isSel && <span style={{ color:"var(--green)", fontWeight:700, fontSize:12 }}>✓</span>}
                  </button>
                );
              })}
            </div>
          </>
        )}
      </div>
    );
  }

  return (
    <div style={{ position:"fixed", top:0, left:0, right:0, bottom:0, background:"rgba(0,0,0,0.42)", zIndex:200, display:"flex", alignItems:"center", justifyContent:"center" }}
      onClick={function(e){ if (e.target === e.currentTarget) onClose(); }}>
      {/* Modal sizing: the form view auto-sizes to its content (so the initial state doesn't
          look stranded inside an oversized frame) while the template view locks to a fixed
          height — that way filtering / search results don't reflow the modal under the cursor. */}
      <div style={{ width:"92vw", maxWidth: view === "template" ? 880 : 720, height: view === "template" ? "min(86vh, 760px)" : "auto", maxHeight:"94vh", background:"var(--bg-canvas)", borderRadius:12, border:"1px solid var(--line)", display:"flex", flexDirection:"column", overflow:"hidden", boxShadow:"0 32px 80px rgba(0,0,0,0.32)" }}>

        {/* HEADER */}
        <div style={{ flexShrink:0, padding:"18px 22px 16px", borderBottom:"1px solid var(--line)", display:"flex", alignItems:"flex-start", justifyContent:"space-between", background:"var(--panel)" }}>
          <div style={{ display:"flex", alignItems:"center", gap:12 }}>
            {view === "template" && (
              <button onClick={function(){ setView("form"); }} title="Back to details" className="btn-ghost"
                style={{ width:32, height:32, borderRadius:"50%", border:"1px solid var(--line)", background:"var(--panel)", display:"inline-flex", alignItems:"center", justifyContent:"center", padding:0, cursor:"pointer", color:"var(--ink-2)" }}>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
              </button>
            )}
            <div>
              <div style={{ fontFamily:"JetBrains Mono", fontSize:10, letterSpacing:"0.8px", color:"var(--ink-3)", textTransform:"uppercase", marginBottom:4 }}>{view === "template" ? "Choose a template" : "New context graph"}</div>
              <div style={{ fontFamily:"Instrument Serif", fontSize:26, color:"var(--ink)", lineHeight:1.1 }}>{graphName || "Untitled graph"}</div>
            </div>
          </div>
          <button onClick={onClose} style={{ width:32, height:32, borderRadius:"50%", border:"1px solid var(--line)", background:"none", cursor:"pointer", fontSize:15, color:"var(--ink-3)", flexShrink:0 }}>✕</button>
        </div>

        {/* BODY — single column, scrollable. Renders either the form view or the template view. */}
        <div style={{ flex:1, overflowY:"auto", padding:"22px 28px 28px" }}>

          {view === "form" && (
            <>
              {/* NAME + DESCRIPTION */}
              <div style={{ display:"flex", flexDirection:"column", gap:16, marginBottom:24 }}>
                <div>
                  <label style={lbl}>Graph name</label>
                  <input value={graphName} onChange={function(e){ setGraphName(e.target.value); }} placeholder="e.g. Customer 360 Graph" style={inp} autoFocus />
                </div>
                <div>
                  <label style={lbl}>Description</label>
                  <textarea value={graphDesc} onChange={function(e){ setGraphDesc(e.target.value); }} rows={2} placeholder="A one-line summary that will appear on the graph card" style={Object.assign({}, inp, { resize:"vertical", lineHeight:1.55 })} />
                </div>
              </div>

              {/* STARTING POINT — simple two-tile chooser. Icon, title, description. */}
              <div style={{ marginBottom:6 }}>
                <label style={lbl}>Starting point</label>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
                  {[
                    {
                      id:"blank",
                      title:"Start blank",
                      desc:"Empty canvas — add entities and edges as you go.",
                      tone: { bg:"var(--chip)", fg:"var(--ink-2)" },
                      icon: (
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
                          <path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/>
                          <polyline points="14 3 14 8 19 8"/>
                          <line x1="12" y1="13" x2="12" y2="17"/>
                          <line x1="10" y1="15" x2="14" y2="15"/>
                        </svg>
                      )
                    },
                    {
                      id:"template",
                      title:"Choose from template",
                      desc:"Begin from a curated blueprint and customise it.",
                      tone: { bg:"var(--blue-fill)", fg:"var(--blue)" },
                      icon: (
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
                          <rect x="3" y="3" width="7" height="7" rx="1"/>
                          <rect x="14" y="3" width="7" height="7" rx="1"/>
                          <rect x="3" y="14" width="7" height="7" rx="1"/>
                          <rect x="14" y="14" width="7" height="7" rx="1"/>
                        </svg>
                      )
                    }
                  ].map(function(opt){
                    var isOn = startMode === opt.id;
                    return (
                      <button key={opt.id} onClick={function(){ chooseStartMode(opt.id); }}
                        style={{ display:"flex", alignItems:"flex-start", gap:14, padding:"16px 18px", borderRadius:9, border:"1px solid " + (isOn ? "var(--ink)" : "var(--line)"), background:"var(--panel)", boxShadow: isOn ? "0 0 0 2px color-mix(in oklab, var(--ink) 7%, transparent)" : "none", textAlign:"left", cursor:"pointer", fontFamily:"inherit" }}>
                        <span style={{ width:36, height:36, borderRadius:8, background: opt.tone.bg, color: opt.tone.fg, display:"inline-flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>{opt.icon}</span>
                        <div style={{ flex:1, minWidth:0 }}>
                          <div style={{ fontSize:14.5, fontWeight:600, color:"var(--ink)" }}>{opt.title}</div>
                          <div style={{ fontSize:12.5, color:"var(--ink-3)", marginTop:4, lineHeight:1.5 }}>{opt.desc}</div>
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            </>
          )}

          {/* TEMPLATE VIEW — search + filters + template list */}
          {view === "template" && (
            <div style={{ display:"flex", flexDirection:"column", gap:14 }}>

              {/* Search + industry + function — one row */}
              <div style={{ display:"grid", gridTemplateColumns:"1.4fr 1fr 1fr", gap:10 }}>
                <div style={{ position:"relative" }}>
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" style={{ position:"absolute", left:11, top:"50%", transform:"translateY(-50%)", color:"var(--ink-3)", pointerEvents:"none" }}>
                    <circle cx="11" cy="11" r="6" stroke="currentColor" strokeWidth="1.6"/>
                    <path d="M20 20l-3.5-3.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/>
                  </svg>
                  <input value={templateQuery} onChange={function(e){ setTemplateQuery(e.target.value); }} placeholder="Search templates" style={Object.assign({}, inp, { paddingLeft:32 })} autoFocus />
                </div>
                <FilterDropdown value={industry} onChange={setIndustry} options={GRAPH_INDUSTRIES} placeholder="Any industry" />
                <FilterDropdown value={func}     onChange={setFunc}     options={GRAPH_FUNCTIONS}  placeholder="Any function" />
              </div>

              {/* Templates */}
              {visibleSuggestions.length === 0 ? (
                <div style={{ padding:"24px 20px", border:"1px dashed var(--line)", borderRadius:10, background:"var(--panel-2)", color:"var(--ink-3)", fontSize:12.5, lineHeight:1.55 }}>
                  No templates match these filters. Clear them, or go back and pick <b>Start blank</b>.
                </div>
              ) : visibleSuggestions.map(function(sp){
                var isOn = startId === sp.id;
                return (
                  // position:relative so the selected-state ✓ can be absolutely positioned
                  // — that way toggling selection doesn't take any layout width away from
                  // the entity chip strip and the card height stays constant.
                  <div key={sp.id} onClick={function(){ pickStart(sp.id); }}
                    style={{ position:"relative", display:"flex", alignItems:"flex-start", gap:14, padding:"14px 16px", paddingRight:36, border:"1px solid " + (isOn ? "var(--ink)" : "var(--line)"), borderRadius:10, background:"var(--panel)", boxShadow: isOn ? "0 0 0 2px color-mix(in oklab, var(--ink) 7%, transparent)" : "none", cursor:"pointer" }}>
                    <span style={{ width:38, height:38, borderRadius:8, background:sp.accent, color:"#fff", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
                      <FunctionIcon id={(sp.fn && sp.fn[0]) || "enterprise"} size={20} />
                    </span>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
                        <span style={{ fontSize:14, fontWeight:600, color:"var(--ink)" }}>{sp.name}</span>
                        {sp.cdm && (
                          <a href={cdmLink(sp.cdm)} target="_blank" rel="noopener noreferrer"
                            title={"View Microsoft CDM — " + sp.cdm + " (opens GitHub)"}
                            onClick={function(e){ e.stopPropagation(); }}
                            style={{ display:"inline-flex", alignItems:"center", gap:5, fontFamily:"JetBrains Mono", fontSize:9, padding:"1.5px 7px 1.5px 6px", borderRadius:3, background:"transparent", color:"var(--ink-3)", border:"1px solid var(--line-2)", fontWeight:600, letterSpacing:"0.4px", textDecoration:"none" }}>
                            <svg width="8" height="8" viewBox="0 0 10 10" fill="currentColor" style={{ opacity:0.7 }}><rect x="0" y="0" width="4" height="4"/><rect x="6" y="0" width="4" height="4"/><rect x="0" y="6" width="4" height="4"/><rect x="6" y="6" width="4" height="4"/></svg>
                            {"CDM · " + sp.cdm}
                          </a>
                        )}
                      </div>
                      <div style={{ fontSize:12.5, color:"var(--ink-3)", lineHeight:1.5, marginTop:4 }}>{sp.desc}</div>
                      {(function(){
                        var CAP = 10;
                        var shown = sp.entities.slice(0, CAP);
                        var overflow = sp.entities.length - shown.length;
                        return (
                          <div style={{ display:"flex", flexWrap:"wrap", gap:4, marginTop:8, alignItems:"center" }}>
                            {shown.map(function(e){
                              return <span key={e} style={{ fontFamily:"JetBrains Mono", fontSize:10.5, padding:"3px 8px", borderRadius:4, background:"var(--chip)", border:"1px solid var(--line-2)", color:"var(--ink-2)" }}>{e}</span>;
                            })}
                            {overflow > 0 && (
                              <span style={{ fontFamily:"JetBrains Mono", fontSize:10.5, padding:"3px 8px", borderRadius:4, background:"transparent", border:"1px dashed var(--line)", color:"var(--ink-3)", fontWeight:600 }}>{"+" + overflow + " more"}</span>
                            )}
                          </div>
                        );
                      })()}
                    </div>
                    {isOn && <span style={{ position:"absolute", top:14, right:14, color:"var(--green)", fontWeight:700, fontSize:14, lineHeight:1, pointerEvents:"none" }}>✓</span>}
                  </div>
                );
              })}
            </div>
          )}

          {/* legacy step-2 block removed — its contents (industry / function pickers,
              AI tailor textarea, template list) are merged inline above into the
              single-modal redesign. The compile-only wrapper below is kept on the
              `{false}` guard so any orphaned closing tokens still balance. */}
          {false && (
              <div style={{ display:"flex", flexDirection:"column", gap:16 }}>
                {/* Prompt strip — slim composer; merge intent surfaces only when relevant */}
                {(function(){
                  var blankSelected = startId === "__blank";
                  var hasPrompt = userPrompt.trim().length > 0;
                  var attachments = (typeof contextAttachments !== "undefined" && contextAttachments) ? contextAttachments : [];
                  var mergeHint = hasPrompt
                    ? (picked ? "Tailoring " + picked.name + " to your context" : (blankSelected ? "Building from your context only" : "Will tailor whichever template you pick below"))
                    : null;
                  return (
                    <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10 }}>
                        <div style={{ display:"inline-flex", alignItems:"center", gap:7, fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)", letterSpacing:"0.6px", textTransform:"uppercase" }}>
                          <span style={{ fontFamily:"JetBrains Mono", fontSize:9, padding:"1px 5px", borderRadius:3, background:"var(--ink)", color:"var(--bg-canvas)", fontWeight:700, letterSpacing:"0.5px" }}>AI</span>
                          Tailor the template <span style={{ color:"var(--ink-4)", textTransform:"none", letterSpacing:0 }}>— tell us your business so we can shape entities, fields, and edges around you</span>
                        </div>
                        {hasPrompt && (
                          <button onClick={function(){ setUserPrompt(""); }} style={{ background:"none", border:"none", padding:0, fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)", cursor:"pointer", letterSpacing:"0.4px" }}>Clear</button>
                        )}
                      </div>

                      <div style={{ position:"relative", border:"1px solid " + (hasPrompt ? "var(--ink-3)" : "var(--line)"), borderRadius:10, background:"var(--panel)", boxShadow:"inset 0 1px 0 rgba(255,255,255,0.6), 0 1px 0 rgba(40,40,20,0.02)" }}>
                        <textarea
                          value={userPrompt}
                          onChange={function(e){ setUserPrompt(e.target.value); }}
                          rows={5}
                          placeholder="e.g. We're a retail enterprise — focus on store-level inventory, loyalty members, and the in-store ↔ online order journey. Skip procurement entities. Treat each fulfilment as a node, not a property."
                          style={{ width:"100%", padding:"14px 14px 6px", fontSize:13.5, fontFamily:"inherit", color:"var(--ink)", background:"transparent", border:"none", outline:"none", boxSizing:"border-box", resize:"vertical", lineHeight:1.55, minHeight:110 }}
                        />

                        {attachments.length > 0 && (
                          <div style={{ display:"flex", flexWrap:"wrap", gap:6, padding:"4px 12px 6px" }}>
                            {attachments.map(function(att, i){
                              return (
                                <span key={i} style={{ display:"inline-flex", alignItems:"center", gap:6, padding:"4px 8px 4px 6px", borderRadius:6, background:"var(--chip)", border:"1px solid var(--line-2)", fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-2)" }}>
                                  <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
                                  {att.name}
                                  <button onClick={function(){ setContextAttachments(function(a){ return a.filter(function(_, j){ return j !== i; }); }); }} style={{ background:"none", border:"none", padding:0, marginLeft:2, color:"var(--ink-3)", cursor:"pointer", fontSize:12, lineHeight:1 }}>×</button>
                                </span>
                              );
                            })}
                          </div>
                        )}

                        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"8px 10px 9px 10px", borderTop:"1px solid var(--line-2)", background:"var(--panel-2)", borderRadius:"0 0 9px 9px" }}>
                          <label style={{ display:"inline-flex", alignItems:"center", gap:6, padding:"5px 9px", borderRadius:6, border:"1px solid var(--line)", background:"var(--panel)", color:"var(--ink-2)", cursor:"pointer", fontFamily:"JetBrains Mono", fontSize:10.5, letterSpacing:"0.3px" }}>
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"><path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48"/></svg>
                            Attach
                            <input type="file" multiple onChange={function(e){
                              var picked = Array.from(e.target.files || []).map(function(f){ return { name: f.name, size: f.size }; });
                              setContextAttachments(function(a){ return a.concat(picked); });
                              e.target.value = "";
                            }} style={{ display:"none" }} />
                          </label>
                          <span style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-4)" }}>
                            {attachments.length > 0
                              ? attachments.length + " file" + (attachments.length === 1 ? "" : "s") + " attached"
                              : "Drop a data dictionary, ERD, or onboarding doc"}
                          </span>
                        </div>
                      </div>

                      {mergeHint && (
                        <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-4)" }}>{mergeHint}</div>
                      )}
                    </div>
                  );
                })()}

                {suggestions.length === 0 && (
                  <div style={{ padding:"24px 20px", border:"1px dashed var(--line)", borderRadius:10, background:"var(--panel-2)", color:"var(--ink-3)", fontSize:12.5, lineHeight:1.55 }}>
                    No curated starting points for this combination yet — pick "Blank canvas" above and build from scratch.
                  </div>
                )}

                {suggestions.map(function(sp){
                  var isOn = startId === sp.id;
                  return (
                    <div key={sp.id} onClick={function(){ pickStart(sp.id); }}
                      style={{ display:"flex", alignItems:"flex-start", gap:14, padding:"14px 16px", border:"1px solid " + (isOn ? "var(--ink)" : "var(--line)"), borderRadius:10, background: isOn ? "var(--bg-canvas)" : "var(--panel)", boxShadow: isOn ? "0 0 0 2px color-mix(in oklab, var(--ink) 7%, transparent)" : "none", cursor:"pointer" }}>
                      <span style={{ width:42, height:42, borderRadius:8, background:sp.accent, color:"#fff", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0 }}>
                        <FunctionIcon id={(sp.fn && sp.fn[0]) || "enterprise"} size={22} />
                      </span>
                      <div style={{ flex:1, minWidth:0 }}>
                        <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap" }}>
                          <span style={{ fontSize:14, fontWeight:600, color:"var(--ink)" }}>{sp.name}</span>
                          {sp.cdm && (
                            <a href={cdmLink(sp.cdm)} target="_blank" rel="noopener noreferrer"
                              title={"View Microsoft CDM — " + sp.cdm + " (opens GitHub)"}
                              onClick={function(e){ e.stopPropagation(); }}
                              style={{ display:"inline-flex", alignItems:"center", gap:5, fontFamily:"JetBrains Mono", fontSize:9, padding:"1.5px 7px 1.5px 6px", borderRadius:3, background:"transparent", color:"var(--ink-3)", border:"1px solid var(--line-2)", fontWeight:600, letterSpacing:"0.4px", textDecoration:"none", cursor:"pointer", transition:"color 100ms, border-color 100ms" }}
                              onMouseEnter={function(e){ e.currentTarget.style.color = "var(--ink)"; e.currentTarget.style.borderColor = "var(--ink-3)"; }}
                              onMouseLeave={function(e){ e.currentTarget.style.color = "var(--ink-3)"; e.currentTarget.style.borderColor = "var(--line-2)"; }}>
                              <svg width="8" height="8" viewBox="0 0 10 10" fill="currentColor" style={{ opacity:0.7 }}><rect x="0" y="0" width="4" height="4"/><rect x="6" y="0" width="4" height="4"/><rect x="0" y="6" width="4" height="4"/><rect x="6" y="6" width="4" height="4"/></svg>
                              {"CDM · " + sp.cdm}
                              <svg width="7" height="7" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.4" style={{ opacity:0.5, marginLeft:1 }}><path d="M3 1 H9 V7 M9 1 L1 9"/></svg>
                            </a>
                          )}
                        </div>
                        <div style={{ fontSize:12.5, color:"var(--ink-3)", lineHeight:1.5, marginTop:5, maxWidth:620 }}>{sp.desc}</div>

                        {(function(){
                          var CAP = 12;
                          var shown = sp.entities.slice(0, CAP);
                          var overflow = sp.entities.length - shown.length;
                          return (
                            <div style={{ display:"flex", flexWrap:"wrap", gap:4, marginTop:10, alignItems:"center" }}>
                              {shown.map(function(e){
                                return <span key={e} style={{ fontFamily:"JetBrains Mono", fontSize:10.5, padding:"3px 8px", borderRadius:4, background:"var(--chip)", border:"1px solid var(--line-2)", color:"var(--ink-2)" }}>{e}</span>;
                              })}
                              {overflow > 0 && (
                                <span title={"Plus " + overflow + " more — see the Entities step"} style={{ fontFamily:"JetBrains Mono", fontSize:10.5, padding:"3px 8px", borderRadius:4, background:"transparent", border:"1px dashed var(--line)", color:"var(--ink-3)", fontWeight:600 }}>{"+" + overflow + " more"}</span>
                              )}
                            </div>
                          );
                        })()}

                      </div>
                      {isOn && <span style={{ color:"var(--green)", fontWeight:700, fontSize:14 }}>✓</span>}
                    </div>
                  );
                })}

                <div style={{ fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-3)", marginTop:8, lineHeight:1.5, padding:"10px 14px", background:"var(--panel-2)", border:"1px dashed var(--line-2)", borderRadius:7 }}>
                  Need more entities than the blueprint provides? You'll be able to add custom ones in the next step.
                </div>
              </div>
            )}

          {/* legacy step-3 block dropped — name + description are inline at the top of the
              redesigned modal; no separate review step. */}

        </div>
        {/* ↑ closes body wrapper */}

        {/* FOOTER — CTA changes by view + start mode:
             form view, blank mode    → "Create graph"     (creates immediately)
             form view, template mode → "Choose template"  (advances to template view)
             template view            → "Create graph"     (creates once a template is picked) */}
        <div style={{ flexShrink:0, padding:"14px 22px", borderTop:"1px solid var(--line)", display:"flex", alignItems:"center", justifyContent:"flex-end", gap:8, background:"var(--panel)" }}>
          <button className="btn-ghost" onClick={onClose}>Cancel</button>
          {view === "form" && startMode === "template" ? (
            <button className="btn-dark" disabled={graphName.trim().length < 2} onClick={function(){ setView("template"); }} style={{ opacity: graphName.trim().length >= 2 ? 1 : 0.45 }}>Choose template →</button>
          ) : (
            <button className="btn-dark" disabled={!canActivate} onClick={function(){ if (onCreate) onCreate({ name: graphName, entities: entitiesToInclude, templateId: startId }); onClose(); }} style={{ opacity: canActivate ? 1 : 0.45 }}>Create graph ↵</button>
          )}
        </div>

      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════════════════
// NEW EDGE FLOW — create a new edge type (relationship) in the schema
// Mirrors NewGraphFlow's shell: 5 steps, sidebar left, content right, no rail.
// Steps: Basics → Population → Properties → Governance → Review
// Population is the conceptually-novel step — it asks where edge instances
// come from. Four mutually-exclusive options keep it concrete (no Cypher).
// ═══════════════════════════════════════════════════════════════════════════════

function NewEdgeFlow({ onClose, onCreate, fromNode, toNode, initialLabel, nodes: liveNodes }) {
  var [step, setStep]                 = useState(1);
  var [label, setLabel]               = useState(initialLabel || "");
  var [desc, setDesc]                 = useState("");
  var [fromId, setFromId]             = useState(fromNode ? fromNode.id : null);
  var [toId, setToId]                 = useState(toNode ? toNode.id : null);
  var [cardinality, setCardinality]   = useState("1:N");
  var [inverseLabel, setInverseLabel] = useState("");
  var [requiredAtFrom, setRequiredAtFrom] = useState(false);
  var [symmetric, setSymmetric]       = useState(false);
  // Population
  var [populationKind, setPopulationKind] = useState(null);
  var [popSourceId, setPopSourceId]   = useState(null);
  var [popFromColumn, setPopFromColumn] = useState("");
  var [popToColumn, setPopToColumn]   = useState("");
  var [popRuleText, setPopRuleText]   = useState("");
  var [popAgentId, setPopAgentId]     = useState(null);
  // Properties
  var [edgeProps, setEdgeProps]       = useState([]);
  // Governance
  var [owner, setOwner]               = useState("morgan.lee");
  var [permsRead,  setPermsRead]      = useState([{ kind:"group", id:"everyone",      label:"Everyone in org" }]);
  var [permsWrite, setPermsWrite]     = useState([{ kind:"group", id:"data-platform", label:"data-platform team" }]);
  var [permsAdmin, setPermsAdmin]     = useState([{ kind:"user",  id:"morgan.lee",    label:"Morgan Lee (you)" }]);

  var stepNames = ["Basics", "Properties", "Review"];

  // Prefer the live nodes from App state — module-scope NODES wouldn't
  // include nodes the user has just added on the canvas.
  var _allNodes = (liveNodes && liveNodes.length) ? liveNodes : NODES;
  var nodeOptions   = _allNodes.filter(function(n){ return n.type === "entity"; });
  var sourceOptions = _allNodes.filter(function(n){ return n.type === "source"; });
  var agentOptions  = _allNodes.filter(function(n){ return n.type === "agent"; });
  var fromN = nodeOptions.find(function(n){ return n.id === fromId; });
  var toN   = nodeOptions.find(function(n){ return n.id === toId; });

  function canContinue() {
    if (step === 1) return label.trim().length >= 3 && /^[A-Z_]+$/.test(label.trim()) && !!fromId && !!toId;
    return true;
  }

  var inp = { border:"1px solid var(--line)", borderRadius:7, padding:"11px 13px", fontSize:13, fontFamily:"inherit", color:"var(--ink)", background:"var(--panel)", outline:"none", boxSizing:"border-box", width:"100%", boxShadow:"inset 0 1px 0 rgba(255,255,255,0.6)" };
  var lbl = { display:"block", fontFamily:"JetBrains Mono", fontSize:9.5, letterSpacing:"0.6px", color:"var(--ink-3)", textTransform:"uppercase", marginBottom:6 };

  var DIRECTORY = [
    { kind:"group", id:"everyone",        label:"Everyone in org" },
    { kind:"group", id:"data-platform",   label:"data-platform team" },
    { kind:"group", id:"customer-ops",    label:"customer-ops team" },
    { kind:"group", id:"finance-ops",     label:"finance-ops team" },
    { kind:"group", id:"engineering",     label:"engineering team" },
    { kind:"group", id:"security",        label:"security team" },
    { kind:"user",  id:"morgan.lee",      label:"Morgan Lee" },
    { kind:"user",  id:"ramin.k",         label:"Ramin K" },
    { kind:"user",  id:"jordan.s",        label:"Jordan S" }
  ];

  // Local node-picker: shows label + state colour. Used for From / To.
  function NodePicker({ value, onChange, placeholder, disabled }) {
    var [open, setOpen] = useState(false);
    var sel = nodeOptions.find(function(n){ return n.id === value; });
    function dot(n){ var c = n.state === "incident" ? "var(--coral)" : n.state === "risk" ? "var(--gold)" : n.state === "signal" ? "var(--purple)" : "var(--blue)"; return c; }
    return (
      <div style={{ position:"relative" }}>
        <button disabled={disabled} onClick={function(){ if (!disabled) setOpen(function(o){ return !o; }); }}
          style={{ display:"flex", alignItems:"center", gap:10, width:"100%", padding:"10px 12px", border:"1px solid " + (sel ? "var(--ink-2)" : "var(--line)"), borderRadius:8, background: disabled ? "var(--panel-2)" : sel ? "var(--bg-canvas)" : "var(--panel)", cursor: disabled ? "default" : "pointer", fontFamily:"inherit", textAlign:"left", opacity: disabled ? 0.85 : 1 }}>
          {sel ? (
            <>
              <span style={{ width:10, height:10, borderRadius:"50%", background: dot(sel), flexShrink:0 }} />
              <span style={{ flex:1, fontSize:13.5, fontWeight:600, color:"var(--ink)" }}>{sel.label}</span>
              {disabled && <span style={{ fontFamily:"JetBrains Mono", fontSize:9, padding:"2px 6px", borderRadius:3, background:"var(--chip)", color:"var(--ink-3)", letterSpacing:"0.5px" }}>LOCKED</span>}
              {!disabled && <span style={{ color:"var(--ink-3)", fontSize:11, fontFamily:"JetBrains Mono" }}>▾</span>}
            </>
          ) : (
            <>
              <span style={{ flex:1, fontSize:13.5, color:"var(--ink-3)" }}>{placeholder}</span>
              <span style={{ color:"var(--ink-3)", fontSize:11, fontFamily:"JetBrains Mono" }}>▾</span>
            </>
          )}
        </button>
        {open && (
          <>
            <div style={{ position:"fixed", top:0, left:0, right:0, bottom:0, zIndex:99 }} onClick={function(){ setOpen(false); }} />
            <div style={{ position:"absolute", top:"calc(100% + 6px)", left:0, right:0, zIndex:100, background:"var(--panel)", border:"1px solid var(--line)", borderRadius:9, boxShadow:"0 14px 38px rgba(0,0,0,0.18)", padding:5, maxHeight:300, overflowY:"auto" }}>
              {nodeOptions.map(function(n){
                var isSel = n.id === value;
                return (
                  <button key={n.id} onClick={function(){ onChange(n.id); setOpen(false); }}
                    style={{ display:"flex", alignItems:"center", gap:10, width:"100%", padding:"8px 10px", borderRadius:6, border:"none", background: isSel ? "var(--bg-canvas)" : "transparent", cursor:"pointer", fontFamily:"inherit", textAlign:"left", fontSize:13, color:"var(--ink)" }}
                    onMouseEnter={function(e){ if (!isSel) e.currentTarget.style.background = "var(--panel-2)"; }}
                    onMouseLeave={function(e){ if (!isSel) e.currentTarget.style.background = "transparent"; }}>
                    <span style={{ width:10, height:10, borderRadius:"50%", background: dot(n), flexShrink:0 }} />
                    <span style={{ flex:1 }}>{n.label}</span>
                    <span style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-4)" }}>{n.instances}</span>
                    {isSel && <span style={{ color:"var(--green)", fontWeight:700, fontSize:12 }}>✓</span>}
                  </button>
                );
              })}
            </div>
          </>
        )}
      </div>
    );
  }

  // Permission row (same RBAC pattern as NewGraphFlow)
  // ── POPULATION OPTIONS ────────────────────────────────────────────────
  var populationOptions = [
    { id:"source", title:"From a data source",   tag:"RECOMMENDED",
      desc:"Join two tables. Pick the system that already has this relationship and tell us which column on each side identifies it.",
      best:"Best when the relationship is already represented as a foreign key in your data (e.g. orders.customer_id → customers.id)." },
    { id:"inferred", title:"Inferred by a rule", tag:"",
      desc:"Create the edge whenever a plain-English condition is met. We translate the rule into a query at sync time.",
      best:"Best when the relationship can be computed from existing properties of the two nodes." },
    { id:"agent", title:"Maintained by an agent", tag:"AGENT",
      desc:"An agent watches your data and adds or removes edges as things change.",
      best:"Best when the relationship needs ongoing judgement — risk attribution, identity resolution, semantic links." },
    { id:"manual", title:"Created manually",      tag:"",
      desc:"Admins and stewards add or remove instances through the catalog UI. The graph holds no automatic logic.",
      best:"Best when the relationship is curated by humans — canonical mappings, golden-record overrides, exception lists." }
  ];

  // ── COMMON EDGE PROPERTY EXAMPLES ─────────────────────────────────────
  var EDGE_PROPERTY_TEMPLATES = [
    { name:"weight",         type:"number",   hint:"Strength of the relationship (0–1)" },
    { name:"confidence",     type:"number",   hint:"How sure the source/agent is" },
    { name:"since",          type:"datetime", hint:"When the relationship started" },
    { name:"until",          type:"datetime", hint:"When the relationship ended (null = active)" },
    { name:"source_system",  type:"string",   hint:"Which system asserted the edge" },
    { name:"is_primary",     type:"boolean",  hint:"Is this the canonical/primary link" }
  ];

  function addProp(template){
    setEdgeProps(function(arr){ return arr.concat([{ name: template.name, type: template.type, required: false }]); });
  }
  function updateProp(idx, patch){
    setEdgeProps(function(arr){ return arr.map(function(p, i){ return i === idx ? Object.assign({}, p, patch) : p; }); });
  }
  function removeProp(idx){
    setEdgeProps(function(arr){ return arr.filter(function(_, i){ return i !== idx; }); });
  }

  return (
    <div style={{ position:"fixed", top:0, left:0, right:0, bottom:0, background:"rgba(0,0,0,0.42)", zIndex:200, display:"flex", alignItems:"center", justifyContent:"center" }}
      onClick={function(e){ if (e.target === e.currentTarget) onClose(); }}>
      <div style={{ width:"92vw", maxWidth:1180, height:"94vh", background:"var(--bg-canvas)", borderRadius:12, border:"1px solid var(--line)", display:"flex", flexDirection:"column", overflow:"hidden", boxShadow:"0 32px 80px rgba(0,0,0,0.32)" }}>

        {/* HEADER */}
        <div style={{ flexShrink:0, height:56, borderBottom:"1px solid var(--line)", display:"flex", alignItems:"center", justifyContent:"space-between", padding:"0 22px", background:"var(--panel)" }}>
          <div style={{ display:"flex", alignItems:"center", gap:14 }}>
            <div style={{ fontFamily:"Instrument Serif", fontSize:20, color:"var(--ink)" }}>{label ? ":" + label : "New edge type"}</div>
            {fromN && toN && (
              <div style={{ display:"flex", alignItems:"center", gap:6, fontFamily:"JetBrains Mono", fontSize:11, color:"var(--ink-3)" }}>
                <span>{fromN.label}</span>
                <span style={{ color:"var(--ink-4)" }}>—{cardinality}→</span>
                <span>{toN.label}</span>
              </div>
            )}
          </div>
          <button onClick={onClose} style={{ width:32, height:32, borderRadius:"50%", border:"1px solid var(--line)", background:"none", cursor:"pointer", fontSize:15, color:"var(--ink-3)" }}>✕</button>
        </div>

        <div style={{ flex:1, display:"grid", gridTemplateColumns:"240px minmax(0, 1fr)", minHeight:0 }}>

          {/* SIDEBAR */}
          <div style={{ background:"var(--panel-2)", borderRight:"1px solid var(--line)", padding:"20px 14px", display:"flex", flexDirection:"column", gap:4, overflowY:"auto" }}>
            {stepNames.map(function(nm, i){
              var n = i + 1;
              var isOn = step === n;
              var isDone = step > n;
              var sub = n === 1 ? (label && fromN && toN ? ":" + label + (populationKind ? " · " + (populationOptions.find(function(o){return o.id===populationKind;}) || {}).title : "") : "Label, endpoints & population")
                      : n === 2 ? (edgeProps.length === 0 ? "None — optional" : edgeProps.length + " propert" + (edgeProps.length === 1 ? "y" : "ies"))
                      : "Publish";
              return (
                <button key={n} onClick={function(){ if (n < step || canContinue()) setStep(n); }}
                  style={{ display:"flex", gap:12, padding:"10px 12px", borderRadius:7, border: isOn ? "1px solid var(--line)" : "1px solid transparent", background: isOn ? "var(--bg-canvas)" : "transparent", cursor:"pointer", fontFamily:"inherit", textAlign:"left", alignItems:"center" }}>
                  <span style={{ width:28, height:28, borderRadius:"50%", border:"1px solid " + (isDone ? "var(--green)" : isOn ? "var(--ink)" : "var(--line)"), background: isDone ? "var(--green)" : isOn ? "var(--ink)" : "var(--bg-canvas)", color: isDone || isOn ? "var(--bg-canvas)" : "var(--ink-3)", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"JetBrains Mono", fontSize: 12, fontWeight:700, flexShrink:0, lineHeight:1 }}>{isDone ? <svg width="15" height="15" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round"><polyline points="3.5,8.5 6.5,11.5 12.5,5" /></svg> : n}</span>
                  <div style={{ minWidth:0 }}>
                    <div style={{ fontSize:13, color:"var(--ink)", fontWeight: isOn ? 500 : 400, lineHeight:1.2 }}>{nm}</div>
                    <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)", marginTop:3, lineHeight:1.3, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{sub}</div>
                  </div>
                </button>
              );
            })}
          </div>

          {/* CENTER */}
          <div style={{ padding:"24px 32px 28px", overflowY:"auto" }}>
            <div style={{ marginBottom:20 }}>
              <div style={{ fontFamily:"JetBrains Mono", fontSize:10, letterSpacing:"0.8px", color:"var(--ink-3)", textTransform:"uppercase", marginBottom:5 }}>{"STEP " + step + " / 3"}</div>
              <div style={{ fontFamily:"Instrument Serif", fontSize:28, color:"var(--ink)", lineHeight:1.1, marginBottom:8 }}>{stepNames[step-1]}</div>
              <div style={{ fontSize:13, color:"var(--ink-3)", lineHeight:1.55 }}>
                {step === 1 && "Name the relationship, pick the two node types it connects, and decide how instances are populated. The label reads like a verb — :WORKS_AT, :BILLED_AS, :OWNS."}
                {step === 2 && "Optional. Add properties that vary per edge — like a weight, a confidence score, or when the relationship started. Skip if every instance is identical."}
                {step === 3 && "Last look before this edge type becomes available to agents, queries and the schema."}
              </div>
            </div>

            {/* STEP 1 — Basics */}
            {step === 1 && (
              <div style={{ display:"flex", flexDirection:"column", gap:22 }}>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:14 }}>
                  <div>
                    <label style={lbl}>LABEL <span style={{ color:"var(--coral)", marginLeft:4 }}>required</span></label>
                    <div style={{ position:"relative" }}>
                      <span style={{ position:"absolute", left:11, top:"50%", transform:"translateY(-50%)", fontFamily:"JetBrains Mono", fontSize:13, color:"var(--ink-4)", pointerEvents:"none" }}>:</span>
                      <input value={label} onChange={function(e){ setLabel(e.target.value.toUpperCase().replace(/[^A-Z_]/g, "")); }} placeholder="WORKS_AT" style={Object.assign({}, inp, { paddingLeft:22, fontFamily:"JetBrains Mono" })} autoFocus />
                    </div>
                    <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)", marginTop:5 }}>UPPER_SNAKE_CASE · 3–32 chars</div>
                  </div>
                  <div>
                    <label style={lbl}>CARDINALITY</label>
                    <div style={{ display:"flex", gap:6 }}>
                      {[
                        { v:"1:1", h:"One on each side" },
                        { v:"1:N", h:"One source, many targets" },
                        { v:"N:1", h:"Many sources, one target" },
                        { v:"N:M", h:"Many on each side" }
                      ].map(function(o){
                        var isOn = cardinality === o.v;
                        return <button key={o.v} title={o.h} onClick={function(){ setCardinality(o.v); }}
                          style={{ flex:1, padding:"8px 0", border:"1px solid " + (isOn ? "var(--ink)" : "var(--line)"), borderRadius:7, background: isOn ? "var(--ink)" : "var(--panel)", color: isOn ? "var(--bg-canvas)" : "var(--ink-2)", fontSize:12, fontFamily:"JetBrains Mono", cursor:"pointer", fontWeight:600 }}>{o.v}</button>;
                      })}
                    </div>
                  </div>
                </div>

                <div>
                  <label style={lbl}>DESCRIPTION <span style={{ color:"var(--ink-4)", marginLeft:4, fontWeight:400 }}>optional</span></label>
                  <textarea value={desc} onChange={function(e){ setDesc(e.target.value); }} rows={2} placeholder="What does this edge represent? Read it both directions out loud — does it work?" style={Object.assign({}, inp, { resize:"vertical", lineHeight:1.55 })} />
                </div>

                <div style={{ display:"grid", gridTemplateColumns:"1fr 60px 1fr", gap:12, alignItems:"end" }}>
                  <div>
                    <label style={lbl}>FROM <span style={{ color:"var(--coral)", marginLeft:4 }}>required</span></label>
                    <NodePicker value={fromId} onChange={setFromId} placeholder="— pick the source node —" />
                  </div>
                  <div style={{ paddingBottom:10, textAlign:"center", fontFamily:"JetBrains Mono", fontSize:14, color:"var(--ink-3)" }}>—{cardinality}→</div>
                  <div>
                    <label style={lbl}>TO <span style={{ color:"var(--coral)", marginLeft:4 }}>required</span></label>
                    <NodePicker value={toId} onChange={setToId} placeholder="— pick the target node —" />
                  </div>
                </div>

                <div>
                  <label style={lbl}>INVERSE LABEL <span style={{ color:"var(--ink-4)", marginLeft:4, fontWeight:400 }}>optional</span></label>
                  <div style={{ position:"relative" }}>
                    <span style={{ position:"absolute", left:11, top:"50%", transform:"translateY(-50%)", fontFamily:"JetBrains Mono", fontSize:13, color:"var(--ink-4)", pointerEvents:"none" }}>:</span>
                    <input value={inverseLabel} onChange={function(e){ setInverseLabel(e.target.value.toUpperCase().replace(/[^A-Z_]/g, "")); }} placeholder="HAS_EMPLOYEE" style={Object.assign({}, inp, { paddingLeft:22, fontFamily:"JetBrains Mono", maxWidth:340 })} />
                  </div>
                  <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)", marginTop:5 }}>Lets queries traverse the reverse direction by name without recomputing.</div>
                </div>

                <div>
                  <label style={lbl}>FLAGS</label>
                  <div style={{ display:"flex", gap:10 }}>
                    {[
                      { v:requiredAtFrom, set:setRequiredAtFrom, l:"Required at From", d:"Every source instance must have at least one of these edges." },
                      { v:symmetric,      set:setSymmetric,      l:"Symmetric / undirected", d:"Direction doesn't matter — useful for peer relationships." }
                    ].map(function(o, i){
                      return (
                        <label key={i} title={o.d}
                          style={{ flex:1, display:"flex", alignItems:"center", gap:8, padding:"10px 12px", border:"1px solid var(--line)", borderRadius:7, background:"var(--panel)", cursor:"pointer" }}>
                          <input type="checkbox" checked={o.v} onChange={function(){ o.set(!o.v); }} style={{ accentColor:"var(--ink)", width:14, height:14 }} />
                          <div>
                            <div style={{ fontSize:13, fontWeight:500, color:"var(--ink)" }}>{o.l}</div>
                            <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)", marginTop:2 }}>{o.d}</div>
                          </div>
                        </label>
                      );
                    })}
                  </div>
                </div>

                {/* HOW IS THIS POPULATED — was its own step */}
                <div>
                  <label style={lbl}>HOW IS THIS POPULATED?</label>
                  <RichSelect
                    value={populationKind || ""}
                    onChange={setPopulationKind}
                    options={populationOptions.map(function(o){ return { value:o.id, label:o.title, sub:o.tag }; })}
                    placeholder="— pick a population mode —"
                  />
                  <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-4)", marginTop:6, lineHeight:1.5 }}>
                    {populationKind ? (populationOptions.find(function(o){ return o.id === populationKind; }) || {}).desc : "From a data source · Inferred by a rule · Maintained by an agent · Computed from a property match."}
                  </div>
                </div>

                {/* OWNER — optional inline (was its own Governance step) */}
                <div>
                  <label style={lbl}>OWNER <span style={{ color:"var(--ink-4)", marginLeft:4, fontWeight:400, textTransform:"none", letterSpacing:0 }}>optional</span></label>
                  <select value={owner} onChange={function(e){ setOwner(e.target.value); }} style={inp}>
                    <option value="morgan.lee">Morgan Lee (you · data-platform)</option>
                    <option value="ramin.k">Ramin K · data-platform</option>
                    <option value="jordan.s">Jordan S · customer-ops</option>
                  </select>
                  <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-4)", marginTop:6, lineHeight:1.5 }}>{"Who gets paged when this edge breaks. Access inherits from the endpoint nodes."}</div>
                </div>
              </div>
            )}


            {/* STEP 2 — Properties */}
            {step === 2 && (
              <div style={{ display:"flex", flexDirection:"column", gap:18 }}>
                {edgeProps.length === 0 ? (
                  <div style={{ padding:"20px 22px", border:"1px dashed var(--line)", borderRadius:10, background:"var(--panel-2)" }}>
                    <div style={{ fontSize:13.5, color:"var(--ink-2)", lineHeight:1.55, marginBottom:6 }}>No properties yet — that's fine for most edges.</div>
                    <div style={{ fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-3)", lineHeight:1.55 }}>Add a property only if every instance can carry a different value for it.</div>
                  </div>
                ) : (
                  <div className="card" style={{ background:"var(--panel)", border:"1px solid var(--line)", borderRadius:10, overflow:"hidden" }}>
                    <div className="card-head card-head-row" style={{ background:"var(--panel-2)" }}>
                      <span style={{ fontSize:13.5, fontWeight:600 }}>Edge properties</span>
                      <span className="card-head-sub">{edgeProps.length}</span>
                    </div>
                    <div>
                      {edgeProps.map(function(p, i){
                        return (
                          <div key={i} style={{ display:"grid", gridTemplateColumns:"1.4fr 1fr auto auto", gap:10, padding:"10px 18px", borderBottom: i < edgeProps.length-1 ? "1px solid var(--line-2)" : "none", alignItems:"center" }}>
                            <input value={p.name} onChange={function(e){ updateProp(i, { name: e.target.value }); }} placeholder="property name" style={Object.assign({}, inp, { fontFamily:"JetBrains Mono", fontSize:12 })} />
                            <select value={p.type} onChange={function(e){ updateProp(i, { type: e.target.value }); }} style={inp}>
                              <option value="string">string</option>
                              <option value="number">number</option>
                              <option value="boolean">boolean</option>
                              <option value="datetime">datetime</option>
                              <option value="json">json</option>
                            </select>
                            <label style={{ display:"flex", alignItems:"center", gap:6, fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-2)" }}>
                              <input type="checkbox" checked={p.required} onChange={function(){ updateProp(i, { required: !p.required }); }} style={{ accentColor:"var(--ink)", width:14, height:14 }} />
                              REQUIRED
                            </label>
                            <button onClick={function(){ removeProp(i); }} style={{ background:"none", border:"none", color:"var(--ink-3)", cursor:"pointer", fontSize:16 }}>×</button>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}

                <div>
                  <div style={{ fontFamily:"JetBrains Mono", fontSize:9.5, color:"var(--ink-3)", letterSpacing:"0.6px", textTransform:"uppercase", marginBottom:10 }}>Quick add — common edge properties</div>
                  <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:8 }}>
                    {EDGE_PROPERTY_TEMPLATES.map(function(t){
                      var already = edgeProps.find(function(p){ return p.name === t.name; });
                      return (
                        <button key={t.name} onClick={function(){ if (!already) addProp(t); }} disabled={!!already}
                          style={{ textAlign:"left", padding:"10px 12px", border:"1px solid var(--line)", borderRadius:7, background: already ? "var(--panel-2)" : "var(--panel)", cursor: already ? "default" : "pointer", fontFamily:"inherit", opacity: already ? 0.5 : 1 }}>
                          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
                            <span style={{ fontFamily:"JetBrains Mono", fontSize:11.5, fontWeight:600, color:"var(--ink)" }}>{t.name}</span>
                            <span style={{ fontFamily:"JetBrains Mono", fontSize:9, color:"var(--ink-3)" }}>{t.type}</span>
                          </div>
                          <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)", marginTop:4, lineHeight:1.4 }}>{t.hint}</div>
                        </button>
                      );
                    })}
                  </div>
                </div>

                <button onClick={function(){ addProp({ name:"", type:"string" }); }} className="btn-ghost" style={{ alignSelf:"flex-start", padding:"8px 14px" }}>+ Add custom property</button>
              </div>
            )}

            {/* STEP 3 — Review */}
            {step === 3 && (
              <div style={{ display:"flex", flexDirection:"column", gap:22 }}>
                <div className="card" style={{ background:"var(--panel)", border:"1px solid var(--line)", borderRadius:10, overflow:"hidden" }}>
                  <div className="card-head card-head-row" style={{ background:"var(--panel-2)" }}>
                    <span style={{ fontSize:14, fontWeight:600 }}>Summary</span>
                    <span className="card-head-sub">{cardinality + " · " + (populationKind || "no population")}</span>
                  </div>
                  <div>
                    {[
                      { k:"LABEL",       v: label ? <span style={{ fontFamily:"JetBrains Mono" }}>{":" + label}</span> : <span style={{ color:"var(--coral)" }}>not set</span> },
                      { k:"FROM → TO",   v: (fromN && toN) ? (fromN.label + "  —" + cardinality + "→  " + toN.label) : <span style={{ color:"var(--coral)" }}>endpoints missing</span> },
                      { k:"INVERSE",     v: inverseLabel ? <span style={{ fontFamily:"JetBrains Mono" }}>{":" + inverseLabel}</span> : <span style={{ color:"var(--ink-4)" }}>—</span> },
                      { k:"FLAGS",       v: [requiredAtFrom && "Required at From", symmetric && "Symmetric"].filter(Boolean).join(" · ") || <span style={{ color:"var(--ink-4)" }}>none</span> },
                      { k:"POPULATION",  v: populationKind === "source"   ? "From source · " + ((sourceOptions.find(function(s){ return s.id === popSourceId; }) || {}).label || "—") + "  ·  " + popFromColumn + " = " + popToColumn
                                            : populationKind === "inferred" ? "Inferred · " + (popRuleText.length > 80 ? popRuleText.slice(0,80) + "…" : popRuleText)
                                            : populationKind === "agent"    ? "Agent · " + ((agentOptions.find(function(a){ return a.id === popAgentId; }) || {}).label || "—")
                                            : populationKind === "manual"   ? "Manual — managed by stewards"
                                            : <span style={{ color:"var(--coral)" }}>not chosen</span> },
                      { k:"PROPERTIES",  v: edgeProps.length === 0 ? <span style={{ color:"var(--ink-4)" }}>none</span> : edgeProps.map(function(p, i){ return <span key={i} style={{ fontFamily:"JetBrains Mono", fontSize:11, padding:"2px 7px", borderRadius:4, background:"var(--chip)", color:"var(--ink-2)", marginRight:4 }}>{p.name + ":" + p.type}</span>; }) },
                      { k:"DESCRIPTION", v: desc || <span style={{ color:"var(--ink-4)" }}>—</span> },
                      { k:"OWNER",       v: owner }
                    ].map(function(row, i, arr){
                      return (
                        <div key={i} style={{ display:"grid", gridTemplateColumns:"170px 1fr", gap:14, padding:"10px 22px", borderBottom: i < arr.length-1 ? "1px dashed var(--line-2)" : "none", alignItems:"baseline" }}>
                          <span style={{ fontFamily:"JetBrains Mono", fontSize:10, letterSpacing:"0.5px", color:"var(--ink-3)", textTransform:"uppercase" }}>{row.k}</span>
                          <span style={{ fontSize:13, color:"var(--ink)", textAlign:"right" }}>{row.v}</span>
                        </div>
                      );
                    })}
                  </div>
                </div>

              </div>
            )}

          </div>
        </div>

        {/* FOOTER */}
        <div style={{ flexShrink:0, padding:"14px 22px", borderTop:"1px solid var(--line)", display:"flex", alignItems:"center", justifyContent:"space-between", background:"var(--panel)" }}>
          <button className="btn-ghost" onClick={function(){ if (step > 1) setStep(function(s){ return s - 1; }); }} disabled={step === 1} style={{ opacity: step === 1 ? 0.4 : 1 }}>← Back</button>
          <span style={{ fontFamily:"JetBrains Mono", fontSize:11, color:"var(--ink-3)" }}>{"Step " + step + " of 3 · " + stepNames[step-1]}</span>
          <div style={{ display:"flex", gap:8 }}>
            <button className="btn-ghost" onClick={onClose}>Cancel</button>
            {step < 3
              ? <button className="btn-dark" disabled={!canContinue()} onClick={function(){ setStep(function(s){ return s + 1; }); }} style={{ opacity: canContinue() ? 1 : 0.45 }}>Continue →</button>
              : <button className="btn-dark" disabled={!canContinue()} onClick={function(){ if (onCreate) onCreate({ label: label, from: fromN, to: toN }); onClose(); }} style={{ opacity: canContinue() ? 1 : 0.45 }}>Create edge type ↵</button>
            }
          </div>
        </div>

      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════════════════════
// GRAPH LANDING — EMPTY STATE
// Shown when a workspace has no graphs yet (or via the E keyboard shortcut on
// the landing). A quiet, ambient node constellation behind a serif hero +
// description + "Create" CTA. Press B to return to the populated view.
// ═══════════════════════════════════════════════════════════════════════════════

function GraphLandingEmpty({ onCreate, onBack }) {
  return (
    <div style={{ flex:1, position:"relative", overflow:"hidden", background:"var(--bg-canvas)", display:"flex", flexDirection:"column" }}>
      {/* Top corner — title chip + back hint */}
      <div style={{ position:"relative", zIndex:2, padding:"22px 32px", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
        <span style={{ fontFamily:"Instrument Serif", fontSize:24, color:"var(--ink)", lineHeight:1 }}>Context Graphs</span>
        <button onClick={onBack} className="btn-ghost" style={{ display:"inline-flex", alignItems:"center", gap:8, fontFamily:"JetBrains Mono", fontSize:11, color:"var(--ink-3)" }}>
          <span>Press</span>
          <span style={{ fontFamily:"JetBrains Mono", fontSize:10.5, padding:"2px 7px", borderRadius:4, background:"var(--panel)", border:"1px solid var(--line)", color:"var(--ink)", fontWeight:700 }}>B</span>
          <span>for populated view</span>
        </button>
      </div>

      {/* Centre hero */}
      <div style={{ position:"relative", zIndex:2, flex:1, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", padding:"12px 24px" }}>
        {/* Brand mark — solid ink tile with a small graph glyph (hub + 4 satellites) */}
        <div style={{ width:84, height:84, borderRadius:18, background:"var(--ink)", display:"flex", alignItems:"center", justifyContent:"center", marginBottom:28, boxShadow:"0 1px 0 var(--line-2), 0 14px 36px rgba(40,40,20,0.14)" }}>
          <svg width="46" height="46" viewBox="0 0 48 48" fill="none" aria-hidden="true">
            {/* edges */}
            <g stroke="var(--bg-canvas)" strokeOpacity="0.45" strokeWidth="1.6" strokeLinecap="round">
              <line x1="24" y1="24" x2="10" y2="10" />
              <line x1="24" y1="24" x2="38" y2="10" />
              <line x1="24" y1="24" x2="10" y2="38" />
              <line x1="24" y1="24" x2="38" y2="38" />
            </g>
            {/* satellites */}
            <g fill="var(--bg-canvas)" fillOpacity="0.75">
              <circle cx="10" cy="10" r="3.4" />
              <circle cx="38" cy="10" r="3.4" />
              <circle cx="10" cy="38" r="3.4" />
              <circle cx="38" cy="38" r="3.4" />
            </g>
            {/* hub */}
            <circle cx="24" cy="24" r="6" fill="var(--bg-canvas)" />
            <circle cx="24" cy="24" r="2.4" fill="var(--ink)" />
          </svg>
        </div>

        <h1 style={{ fontFamily:"Geist, system-ui, sans-serif", fontWeight:600, fontSize:"clamp(40px, 5.4vw, 64px)", lineHeight:1.08, color:"var(--ink)", margin:0, letterSpacing:"-0.022em", textAlign:"center", maxWidth:980 }}>
          Build your enterprise<br/>context graph
        </h1>

        <p style={{ fontFamily:"Geist, system-ui, sans-serif", fontSize:"clamp(14px, 1.25vw, 17px)", color:"var(--ink-2)", lineHeight:1.6, margin:"20px 0 0", maxWidth:680, textAlign:"center" }}>
          One unified layer where every entity — customers, products, employees, contracts, invoices — connects across every system. Agents, analysts and AI reason on the same source of truth, from CRM and ERP to billing, support and beyond.
        </p>


        <div style={{ display:"flex", alignItems:"center", gap:14, marginTop:36 }}>
          <button onClick={onCreate} className="btn-dark" style={{ padding:"12px 22px", fontSize:14, display:"inline-flex", alignItems:"center", gap:8 }}>
            <span style={{ fontSize:16, lineHeight:1, fontWeight:300 }}>+</span>
            Create a context graph
          </button>
          <button onClick={onBack} className="btn-ghost" style={{ padding:"12px 18px", fontSize:13, color:"var(--ink-2)" }}>
            Browse existing graphs
          </button>
        </div>

        {/* Tiny feature trio under the CTA — keeps the centre feeling intentional, not empty */}
        <div style={{ display:"flex", alignItems:"flex-start", gap:32, marginTop:54, flexWrap:"wrap", justifyContent:"center", maxWidth:820 }}>
          {[
            { t:"Pick a template",     d:"Industry blueprints aligned to Microsoft CDM — Healthcare, Banking, Sales, Service and more." },
            { t:"Customise entities",  d:"Add or remove entities from the blueprint. Bring your own properties on top." },
            { t:"Wire your access",    d:"Decide who reads, writes and administers — by team or by person." }
          ].map(function(f, i){
            return (
              <div key={i} style={{ flex:"1 1 220px", maxWidth:240, textAlign:"left" }}>
                <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6 }}>
                  <span style={{ width:20, height:20, borderRadius:5, background:"var(--ink)", color:"var(--bg-canvas)", display:"flex", alignItems:"center", justifyContent:"center", fontFamily:"JetBrains Mono", fontSize:10, fontWeight:700 }}>{i + 1}</span>
                  <span style={{ fontFamily:"Instrument Serif", fontSize:18, color:"var(--ink)" }}>{f.t}</span>
                </div>
                <div style={{ fontFamily:"Geist, system-ui", fontSize:12.5, color:"var(--ink-3)", lineHeight:1.55 }}>{f.d}</div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Bottom hint */}
      <div style={{ position:"relative", zIndex:2, padding:"18px 32px", display:"flex", justifyContent:"center" }}>
        <span style={{ display:"inline-flex", alignItems:"center", gap:8, fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-4)" }}>
          <span style={{ fontFamily:"JetBrains Mono", fontSize:10.5, padding:"2px 7px", borderRadius:4, background:"var(--panel)", border:"1px solid var(--line-2)", color:"var(--ink-3)", fontWeight:700 }}>E</span>
          empty state
          <span style={{ color:"var(--ink-4)" }}>·</span>
          <span style={{ fontFamily:"JetBrains Mono", fontSize:10.5, padding:"2px 7px", borderRadius:4, background:"var(--panel)", border:"1px solid var(--line-2)", color:"var(--ink-3)", fontWeight:700 }}>B</span>
          populated
        </span>
      </div>
    </div>
  );
}

function GraphLandingView({ onOpenGraph }) {
  var [newGraphOpen, setNewGraphOpen] = useState(false);
  var [view, setView]     = useState("grid"); // grid | list
  var [search, setSearch] = useState("");
  var [sort, setSort]     = useState("active");
  var [sortOpen, setSortOpen] = useState(false);
  var [emptyState, setEmptyState] = useState(false);

  // Keyboard shortcuts: E = empty state, B = back to populated.
  // Ignore when typing into an input/textarea so search-in-page still works.
  useEffect(function(){
    function onKey(e){
      var t = e.target;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.isContentEditable)) return;
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      if (e.key === "e" || e.key === "E"){ setEmptyState(true); }
      else if (e.key === "b" || e.key === "B"){ setEmptyState(false); }
    }
    document.addEventListener("keydown", onKey);
    return function(){ document.removeEventListener("keydown", onKey); };
  }, []);

  if (emptyState) {
    return (
      <>
        <GraphLandingEmpty onCreate={function(){ setNewGraphOpen(true); }} onBack={function(){ setEmptyState(false); }} />
        {newGraphOpen && <NewGraphFlow onClose={function(){ setNewGraphOpen(false); }} onCreate={function(g){ setNewGraphOpen(false); setEmptyState(false); if (g && g.id) onOpenGraph(g.id); }} />}
      </>
    );
  }

  var SORT_OPTIONS = [
    { id:"active",    label:"Most active" },
    { id:"nodes",     label:"Most nodes" },
    { id:"recent",    label:"Recently synced" },
    { id:"alpha",     label:"Alphabetical" }
  ];

  var filtered = CONTEXT_GRAPHS.filter(function(g){
    if (!search) return true;
    var q = search.toLowerCase();
    return (g.name + " " + g.desc + " " + g.cat).toLowerCase().indexOf(q) >= 0;
  });

  filtered = filtered.slice().sort(function(a, b){
    if (sort === "nodes")  return b.nodes - a.nodes;
    if (sort === "recent") return parseInt(a.synced) - parseInt(b.synced);
    if (sort === "alpha")  return a.name.localeCompare(b.name);
    return b.nodes - a.nodes; // active fallback — largest first
  });

  var totals = CONTEXT_GRAPHS.reduce(function(acc, g){
    acc.nodes += g.nodes; acc.edges += g.edges; acc.sources += g.sources;
    return acc;
  }, { nodes:0, edges:0, sources:0 });

  function healthColor(h){ return h >= 95 ? "var(--green)" : h >= 90 ? "var(--blue)" : h >= 80 ? "var(--gold)" : "var(--coral)"; }

  return (
    <div style={{ flex:1, overflowY:"auto", background:"var(--bg-canvas)", display:"flex", flexDirection:"column" }}>
      {/* HEADER BAR — like a workspace picker */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:14, padding:"22px 32px 14px", background:"var(--bg)", borderBottom:"1px solid var(--line-2)" }}>
        <div style={{ display:"flex", alignItems:"baseline", gap:14 }}>
          <span style={{ fontFamily:"Instrument Serif", fontSize:30, color:"var(--ink)", lineHeight:1, letterSpacing:"-0.3px" }}>Enterprise Context Graph</span>
        </div>
        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
          <div style={{ position:"relative" }}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" style={{ position:"absolute", left:10, top:"50%", transform:"translateY(-50%)", color:"var(--ink-3)", pointerEvents:"none" }}>
              <circle cx="11" cy="11" r="6" stroke="currentColor" strokeWidth="1.6"/><path d="M20 20l-3.5-3.5" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/>
            </svg>
            <input value={search} onChange={function(e){ setSearch(e.target.value); }} placeholder="Search graphs…" style={{ padding:"7px 12px 7px 32px", border:"1px solid var(--line)", borderRadius:8, fontFamily:"inherit", fontSize:12.5, background:"var(--panel)", color:"var(--ink)", outline:"none", width:260 }} />
          </div>
          {/* View toggle */}
          <div style={{ display:"flex", border:"1px solid var(--line)", borderRadius:8, background:"var(--panel)", padding:2 }}>
            <button onClick={function(){ setView("grid"); }} title="Grid view" style={{ width:30, height:26, border:"none", borderRadius:6, background: view === "grid" ? "var(--bg-canvas)" : "transparent", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", color: view === "grid" ? "var(--ink)" : "var(--ink-3)" }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none"><rect x="3" y="3" width="7" height="7" rx="1" stroke="currentColor" strokeWidth="1.6"/><rect x="14" y="3" width="7" height="7" rx="1" stroke="currentColor" strokeWidth="1.6"/><rect x="3" y="14" width="7" height="7" rx="1" stroke="currentColor" strokeWidth="1.6"/><rect x="14" y="14" width="7" height="7" rx="1" stroke="currentColor" strokeWidth="1.6"/></svg>
            </button>
            <button onClick={function(){ setView("dash"); }} title="Insights view" style={{ width:30, height:26, border:"none", borderRadius:6, background: view === "dash" ? "var(--bg-canvas)" : "transparent", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", color: view === "dash" ? "var(--ink)" : "var(--ink-3)" }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none"><rect x="3" y="3" width="8" height="18" rx="1.2" stroke="currentColor" strokeWidth="1.6"/><rect x="13" y="3" width="8" height="8" rx="1.2" stroke="currentColor" strokeWidth="1.6"/><rect x="13" y="13" width="8" height="8" rx="1.2" stroke="currentColor" strokeWidth="1.6"/></svg>
            </button>
            <button onClick={function(){ setView("list"); }} title="List view" style={{ width:30, height:26, border:"none", borderRadius:6, background: view === "list" ? "var(--bg-canvas)" : "transparent", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", color: view === "list" ? "var(--ink)" : "var(--ink-3)" }}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none"><line x1="4" y1="6" x2="20" y2="6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/><line x1="4" y1="12" x2="20" y2="12" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/><line x1="4" y1="18" x2="20" y2="18" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/></svg>
            </button>
          </div>
          <button className="btn-ghost" style={{ display:"flex", alignItems:"center", gap:6 }}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none"><path d="M3 5h18M6 12h12M10 19h4" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"/></svg>
            Filter
          </button>
          {/* Sort dropdown */}
          <div style={{ position:"relative" }}>
            <button onClick={function(){ setSortOpen(function(o){ return !o; }); }} className="btn-ghost" style={{ display:"flex", alignItems:"center", gap:8 }}>
              <span style={{ color:"var(--ink-3)" }}>Sort:</span>
              <span>{(SORT_OPTIONS.find(function(o){ return o.id === sort; }) || {}).label}</span>
              <svg width="10" height="10" viewBox="0 0 24 24" fill="none" style={{ transform: sortOpen ? "rotate(180deg)" : "none" }}><path d="M6 9l6 6 6-6" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"/></svg>
            </button>
            {sortOpen && (
              <>
                <div style={{ position:"fixed", top:0, left:0, right:0, bottom:0, zIndex:99 }} onClick={function(){ setSortOpen(false); }} />
                <div style={{ position:"absolute", top:"calc(100% + 6px)", right:0, zIndex:100, background:"var(--panel)", border:"1px solid var(--line)", borderRadius:9, boxShadow:"0 8px 28px rgba(0,0,0,0.14)", padding:6, minWidth:180 }}>
                  {SORT_OPTIONS.map(function(o){
                    var isOn = sort === o.id;
                    return <button key={o.id} onClick={function(){ setSort(o.id); setSortOpen(false); }}
                      style={{ display:"flex", alignItems:"center", gap:8, width:"100%", padding:"7px 10px", borderRadius:5, border:"none", background: isOn ? "var(--bg-canvas)" : "transparent", cursor:"pointer", fontFamily:"inherit", fontSize:12.5, color:"var(--ink)", textAlign:"left" }}>
                      <span style={{ flex:1 }}>{o.label}</span>
                      {isOn && <span style={{ color:"var(--green)", fontWeight:700 }}>✓</span>}
                    </button>;
                  })}
                </div>
              </>
            )}
          </div>
          <button className="btn-dark" style={{ padding:"7px 14px" }} onClick={function(){ setNewGraphOpen(true); }}>+ New graph</button>
        </div>
      </div>

      {/* STATS STRIP */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"16px 32px 14px", borderBottom:"1px solid var(--line-2)" }}>
        <span style={{ fontFamily:"JetBrains Mono", fontSize:11, color:"var(--ink-3)", letterSpacing:"0.3px" }}>{filtered.length + " of " + CONTEXT_GRAPHS.length + " context graphs"}</span>
        <div style={{ display:"flex", alignItems:"baseline", gap:32 }}>
          {[
            { lbl:"TOTAL NODES",   v: totals.nodes.toLocaleString(),   color:"var(--ink)" },
            { lbl:"TOTAL EDGES",   v: totals.edges.toLocaleString(),   color:"var(--ink)" },
            { lbl:"TOTAL SOURCES", v: totals.sources.toLocaleString(), color:"var(--ink)" }
          ].map(function(k, i){
            return <div key={i} style={{ display:"flex", flexDirection:"column", gap:3, paddingLeft: i > 0 ? 28 : 0, borderLeft: i > 0 ? "1px solid var(--line-2)" : "none" }}>
              <span style={{ fontFamily:"JetBrains Mono", fontSize:9.5, letterSpacing:"0.6px", color:"var(--ink-3)", textTransform:"uppercase" }}>{k.lbl}</span>
              <span style={{ fontFamily:"Instrument Serif", fontSize:22, lineHeight:1, color:k.color }}>{k.v}</span>
            </div>;
          })}
        </div>
      </div>

      {/* INSIGHTS — stat-rich dashboard cards. Visual through donuts + composition strips + sparklines, no graph viz. */}
      {view === "dash" ? (
        <div style={{ padding:"24px clamp(20px, 4vw, 64px) 40px", width:"100%", boxSizing:"border-box" }}>
          {(function(){
            var ecg = filtered.find(function(g){ return g.id === "ecg"; });
            var rest = filtered.filter(function(g){ return g.id !== "ecg"; });
            var ordered = ecg ? [ecg].concat(rest) : rest;

            function seedRand(seed, n){
              var s = (seed | 0) || 1;
              var out = [];
              for (var i = 0; i < n; i++){ s = (s * 1664525 + 1013904223) | 0; out.push((Math.abs(s) % 1000) / 1000); }
              return out;
            }

            // Per-graph source mix — share of records contributed by each upstream system.
            // Far more meaningful than abstract "composition": it answers "where does this graph's data come from?"
            // Each entry: [source name, % share]. Last entry can be an "Other (n)" rollup for long-tail sources.
            var SOURCE_MIX = {
              ecg:       [["Salesforce", 24], ["NetSuite", 19], ["Workday", 14], ["Other (9)", 43]],
              support:   [["Zendesk", 46], ["Intercom", 24], ["Jira Service", 18], ["Slack Connect", 12]],
              customer:  [["Salesforce", 38], ["HubSpot", 22], ["Stripe", 22], ["Segment", 18]],
              sales:     [["Salesforce", 48], ["HubSpot", 20], ["Outreach", 18], ["LinkedIn SN", 14]],
              finance:   [["NetSuite", 42], ["Stripe", 22], ["Coupa", 18], ["Other (4)", 18]],
              product:   [["Productboard", 32], ["Jira", 28], ["Linear", 22], ["GitHub", 18]],
              security:  [["Okta", 30], ["CrowdStrike", 26], ["Vault", 20], ["Other (5)", 24]],
              workforce: [["Workday", 52], ["BambooHR", 30], ["Greenhouse", 18]],
              risk:      [["Vanta", 38], ["AuditBoard", 26], ["OneTrust", 22], ["Other (3)", 14]]
            };
            function buildSpark(seed){
              // smooth-ish 30-day curve trending up
              var r = seedRand(seed + 7, 30);
              var out = [], prev = 0.4 + r[0]*0.2;
              for (var i = 0; i < 30; i++){
                var target = 0.35 + r[i]*0.55 + (i/30)*0.1;
                prev = prev*0.55 + target*0.45;
                out.push(prev);
              }
              return out;
            }

            var SOURCE_COLORS = ["var(--blue)","var(--green)","var(--gold)","var(--ink-3)"];

            return (
              <div style={{ display:"grid", gridTemplateColumns:"repeat(3, minmax(0, 1fr))", gap:20 }}>
                {ordered.map(function(g){
                  var hColor = healthColor(g.health);
                  var seed = g.id.charCodeAt(0) * 977 + g.id.length * 31;
                  var sourceMix = SOURCE_MIX[g.id] || [["Source A", 40], ["Source B", 35], ["Other", 25]];
                  var spark = buildSpark(seed);
                  var sparkMax = Math.max.apply(null, spark);
                  var sparkMin = Math.min.apply(null, spark);
                  var sparkRange = Math.max(0.001, sparkMax - sparkMin);
                  var W = 200, HH = 34;
                  var pts = spark.map(function(v, i){
                    var x = (i / (spark.length-1)) * W;
                    var y = HH - 2 - ((v - sparkMin) / sparkRange) * (HH - 6);
                    return { x: x, y: y };
                  });
                  var sparkPath = pts.map(function(p, i){ return (i === 0 ? "M" : "L") + p.x.toFixed(1) + " " + p.y.toFixed(1); }).join(" ");
                  var areaPath = sparkPath + " L " + W + " " + HH + " L 0 " + HH + " Z";

                  var donutR = 28, donutC = 2 * Math.PI * donutR;
                  var pct = Math.max(0, Math.min(1, g.health / 100));

                  return (
                    <div key={g.id} onClick={function(){ onOpenGraph(g.id); }}
                      style={{ background:"var(--panel)", border:"1px solid var(--line)", borderRadius:14, padding:"22px 24px 20px", cursor:"pointer", transition:"transform 120ms ease, box-shadow 120ms ease, border-color 120ms ease" }}
                      onMouseEnter={function(e){ e.currentTarget.style.transform = "translateY(-2px)"; e.currentTarget.style.boxShadow = "0 10px 28px rgba(40,40,20,0.08)"; e.currentTarget.style.borderColor = "var(--ink-3)"; }}
                      onMouseLeave={function(e){ e.currentTarget.style.transform = "none"; e.currentTarget.style.boxShadow = "none"; e.currentTarget.style.borderColor = "var(--line)"; }}>
                      {/* HEAD — meta on left, donut on right */}
                      <div style={{ display:"flex", alignItems:"flex-start", justifyContent:"space-between", gap:16, marginBottom:14 }}>
                        <div style={{ minWidth:0, flex:1 }}>
                          <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:8 }}>
                            <span style={{ fontFamily:"JetBrains Mono", fontSize:9.5, letterSpacing:"1.1px", color:"var(--ink-3)", padding:"3px 8px", background:"var(--panel-2)", border:"1px solid var(--line-2)", borderRadius:4 }}>{g.cat}</span>
                            <span style={{ width:3, height:3, borderRadius:"50%", background:"var(--ink-3)" }} />
                            <span style={{ fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-3)" }}>{g.owner}</span>
                          </div>
                          <div style={{ fontFamily:"Instrument Serif", fontSize:24, color:"var(--ink)", lineHeight:1.15, marginBottom:5 }}>{g.name}</div>
                          <div style={{ fontSize:12, color:"var(--ink-3)", lineHeight:1.5, overflow:"hidden", textOverflow:"ellipsis", display:"-webkit-box", WebkitLineClamp:2, WebkitBoxOrient:"vertical" }}>{g.desc}</div>
                        </div>
                        <div style={{ flexShrink:0, position:"relative", width:74, height:74 }}>
                          <svg width="74" height="74" viewBox="0 0 74 74">
                            <circle cx="37" cy="37" r={donutR} fill="none" stroke="var(--line-2)" strokeWidth="5" />
                            <circle cx="37" cy="37" r={donutR} fill="none" stroke={hColor} strokeWidth="5" strokeLinecap="round" strokeDasharray={donutC} strokeDashoffset={donutC * (1 - pct)} transform="rotate(-90 37 37)" />
                          </svg>
                          <div style={{ position:"absolute", inset:0, display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center" }}>
                            <span style={{ fontFamily:"Instrument Serif", fontSize:20, color:"var(--ink)", lineHeight:1 }}>{g.health}</span>
                            <span style={{ fontFamily:"JetBrains Mono", fontSize:7.5, color:"var(--ink-3)", letterSpacing:"0.8px", marginTop:2 }}>HEALTH</span>
                          </div>
                        </div>
                      </div>

                      {/* STATS — three large numbers */}
                      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:14, padding:"14px 0", borderTop:"1px dashed var(--line-2)", borderBottom:"1px dashed var(--line-2)" }}>
                        {[{k:"NODES", v:g.nodes.toLocaleString()},{k:"EDGES", v:g.edges.toLocaleString()},{k:"SOURCES", v:g.sources.toString()}].map(function(it, i){
                          return <div key={i}>
                            <div style={{ fontFamily:"JetBrains Mono", fontSize:9, letterSpacing:"0.7px", color:"var(--ink-3)", textTransform:"uppercase" }}>{it.k}</div>
                            <div style={{ fontFamily:"Instrument Serif", fontSize:22, color:"var(--ink)", marginTop:2, lineHeight:1 }}>{it.v}</div>
                          </div>;
                        })}
                      </div>

                      {/* BY SOURCE — share of records contributed per upstream system */}
                      <div style={{ marginTop:14 }}>
                        <div style={{ display:"flex", alignItems:"baseline", justifyContent:"space-between", marginBottom:8 }}>
                          <span style={{ fontFamily:"JetBrains Mono", fontSize:9, letterSpacing:"0.8px", color:"var(--ink-3)", textTransform:"uppercase" }}>By source</span>
                          <span style={{ fontFamily:"JetBrains Mono", fontSize:9, letterSpacing:"0.4px", color:"var(--ink-4)", textTransform:"uppercase" }}>share of records</span>
                        </div>
                        <div style={{ display:"flex", height:8, borderRadius:4, overflow:"hidden", border:"1px solid var(--line-2)" }}>
                          {sourceMix.map(function(s, i){
                            return <div key={i} style={{ flex: s[1], background: SOURCE_COLORS[i % SOURCE_COLORS.length] }} />;
                          })}
                        </div>
                        <div style={{ display:"flex", flexWrap:"wrap", gap:"6px 14px", marginTop:9 }}>
                          {sourceMix.map(function(s, i){
                            return <span key={i} style={{ display:"flex", alignItems:"center", gap:6, fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-2)" }}>
                              <span style={{ width:7, height:7, borderRadius:2, background: SOURCE_COLORS[i % SOURCE_COLORS.length] }} />
                              <span>{s[0]}</span>
                              <span style={{ color:"var(--ink-3)" }}>{s[1] + "%"}</span>
                            </span>;
                          })}
                        </div>
                      </div>

                      {/* ACTIVITY — area sparkline */}
                      <div style={{ marginTop:16 }}>
                        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:6 }}>
                          <span style={{ fontFamily:"JetBrains Mono", fontSize:9, letterSpacing:"0.8px", color:"var(--ink-3)", textTransform:"uppercase" }}>Activity · last 30 days</span>
                          <span style={{ display:"inline-flex", alignItems:"center", gap:6, fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)" }}>
                            <span style={{ width:6, height:6, borderRadius:"50%", background:"var(--green)" }} />
                            Synced {g.synced}
                          </span>
                        </div>
                        <svg width="100%" height={HH} viewBox={"0 0 " + W + " " + HH} preserveAspectRatio="none" style={{ display:"block" }}>
                          <defs>
                            <linearGradient id={"spark_" + g.id} x1="0" x2="0" y1="0" y2="1">
                              <stop offset="0%" stopColor={g.color} stopOpacity="0.28" />
                              <stop offset="100%" stopColor={g.color} stopOpacity="0" />
                            </linearGradient>
                          </defs>
                          <path d={areaPath} fill={"url(#spark_" + g.id + ")"} />
                          <path d={sparkPath} fill="none" stroke={g.color} strokeWidth="1.4" strokeLinejoin="round" strokeLinecap="round" />
                          <circle cx={pts[pts.length-1].x} cy={pts[pts.length-1].y} r="2.4" fill={g.color} />
                        </svg>
                      </div>
                    </div>
                  );
                })}
              </div>
            );
          })()}
        </div>
      ) : view === "grid" ? (
        <div style={{ padding:"24px clamp(20px, 4vw, 64px) 40px", width:"100%", boxSizing:"border-box", display:"flex", flexDirection:"column", gap:20 }}>
          {(function(){
            // ECG first, then everything else in its current order
            var ecg = filtered.find(function(g){ return g.id === "ecg"; });
            var rest = filtered.filter(function(g){ return g.id !== "ecg"; });
            var ordered = ecg ? [ecg].concat(rest) : rest;
            return (
              <>
                <div style={{ display:"grid", gridTemplateColumns:"repeat(3, minmax(0, 1fr))", gap:20 }}>
                  {ordered.map(function(g, idx){
                    var hColor = healthColor(g.health);
                    return (
                      <div key={g.id}
                        onClick={function(){ onOpenGraph(g.id); }}
                        style={{ background:"var(--panel)", border:"1px solid var(--line)", borderRadius:14, overflow:"hidden", cursor:"pointer", transition:"transform 120ms ease, box-shadow 120ms ease, border-color 120ms ease" }}
                        onMouseEnter={function(e){ e.currentTarget.style.transform = "translateY(-2px)"; e.currentTarget.style.boxShadow = "0 10px 28px rgba(40,40,20,0.08)"; e.currentTarget.style.borderColor = "var(--ink-3)"; }}
                        onMouseLeave={function(e){ e.currentTarget.style.transform = "none"; e.currentTarget.style.boxShadow = "none"; e.currentTarget.style.borderColor = "var(--line)"; }}>
                        <div style={{ position:"relative", height:180, overflow:"hidden" }}>
                          <GraphMiniViz seed={g.id.charCodeAt(0) * 977 + g.id.length * 31} color={g.color} />
                          <span style={{ position:"absolute", top:12, left:14, zIndex:2, fontFamily:"JetBrains Mono", fontSize:9.5, letterSpacing:"1.1px", color:"var(--ink-3)", padding:"3px 8px", background:"var(--panel)", border:"1px solid var(--line-2)", borderRadius:4 }}>{g.cat}</span>
                          <span style={{ position:"absolute", top:12, right:14, zIndex:2, fontFamily:"JetBrains Mono", fontSize:11, color: hColor, display:"flex", alignItems:"center", gap:5, fontWeight:600, padding:"3px 8px", background:"var(--panel)", border:"1px solid var(--line-2)", borderRadius:4 }}>
                            <span style={{ width:6, height:6, borderRadius:"50%", background: hColor }} />{g.health + "%"}
                          </span>
                        </div>
                        <div style={{ padding:"18px 22px 18px" }}>
                          <div style={{ fontFamily:"Instrument Serif", fontSize:22, color:"var(--ink)", lineHeight:1.15, marginBottom:8 }}>{g.name}</div>
                          <div style={{ fontSize:12.5, color:"var(--ink-3)", lineHeight:1.55, marginBottom:14, minHeight:36, display:"-webkit-box", WebkitLineClamp:2, WebkitBoxOrient:"vertical", overflow:"hidden" }}>{g.desc}</div>
                          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:14, paddingTop:12, borderTop:"1px dashed var(--line-2)" }}>
                            {[{ k:"NODES", v: g.nodes.toLocaleString() },{ k:"EDGES", v: g.edges.toLocaleString() },{ k:"SOURCES", v: g.sources.toString() }].map(function(it, i){
                              return <div key={i}>
                                <div style={{ fontFamily:"JetBrains Mono", fontSize:9, letterSpacing:"0.6px", color:"var(--ink-3)", textTransform:"uppercase" }}>{it.k}</div>
                                <div style={{ fontFamily:"Instrument Serif", fontSize:17, color:"var(--ink)", marginTop:2, lineHeight:1 }}>{it.v}</div>
                              </div>;
                            })}
                          </div>
                          <div style={{ marginTop:12, display:"flex", alignItems:"center", gap:6, fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)" }}>
                            <span style={{ width:6, height:6, borderRadius:"50%", background:"var(--green)" }} />
                            <span>Synced {g.synced}</span>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </>
            );
          })()}
        </div>
      ) : (
        // LIST VIEW
        <div style={{ padding:"20px clamp(20px, 4vw, 64px) 40px", width:"100%", boxSizing:"border-box" }}>
          <div style={{ border:"1px solid var(--line)", borderRadius:14, background:"var(--panel)", overflow:"hidden", boxShadow:"0 1px 0 var(--line-2)" }}>
            {/* HEADER */}
            <div style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr) 110px 110px 110px 110px 130px 150px", gap:16, padding:"12px 22px", background:"var(--panel-2)", borderBottom:"1px solid var(--line)", fontFamily:"JetBrains Mono", fontSize:9.5, color:"var(--ink-3)", letterSpacing:"0.8px", textTransform:"uppercase", alignItems:"center" }}>
              <div>Graph</div>
              <div style={{ textAlign:"right" }}>Nodes</div>
              <div style={{ textAlign:"right" }}>Edges</div>
              <div style={{ textAlign:"right" }}>Sources</div>
              <div style={{ textAlign:"center" }}>Health</div>
              <div>Synced</div>
              <div>Owner</div>
            </div>
            {filtered.map(function(g, i){
              var hColor = healthColor(g.health);
              var initials = g.name.split(/\s+/).map(function(p){ return p[0]; }).filter(Boolean).slice(0, 3).join("").toUpperCase();
              return (
                <div key={g.id} onClick={function(){ onOpenGraph(g.id); }}
                  style={{ display:"grid", gridTemplateColumns:"minmax(0, 1fr) 110px 110px 110px 110px 130px 150px", gap:16, padding:"16px 22px", borderBottom: i < filtered.length-1 ? "1px solid var(--line-2)" : "none", cursor:"pointer", alignItems:"center", transition:"background 100ms" }}
                  onMouseEnter={function(e){ e.currentTarget.style.background = "var(--panel-2)"; }}
                  onMouseLeave={function(e){ e.currentTarget.style.background = "transparent"; }}>
                  {/* GRAPH cell — bigger icon + name/desc */}
                  <div style={{ display:"flex", alignItems:"center", gap:14, minWidth:0 }}>
                    {/* Mini graph tile — uses the same GraphMiniViz, scaled down */}
                    <div style={{ width:54, height:42, borderRadius:7, overflow:"hidden", border:"1px solid var(--line-2)", flexShrink:0, background: g.color + "10" }}>
                      <GraphMiniViz seed={g.id.charCodeAt(0) * 977 + g.id.length * 31} color={g.color} />
                    </div>
                    <div style={{ minWidth:0, flex:1 }}>
                      <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:3 }}>
                        <span style={{ fontFamily:"Instrument Serif", fontSize:16, color:"var(--ink)", lineHeight:1.1 }}>{g.name}</span>
                        <span style={{ fontFamily:"JetBrains Mono", fontSize:9, letterSpacing:"0.7px", color:"var(--ink-3)", padding:"1.5px 6px", background:"var(--panel-2)", border:"1px solid var(--line-2)", borderRadius:3, flexShrink:0 }}>{g.cat}</span>
                      </div>
                      <div style={{ fontSize:12, color:"var(--ink-3)", lineHeight:1.4, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{g.desc}</div>
                    </div>
                  </div>
                  <div style={{ fontFamily:"Instrument Serif", fontSize:17, color:"var(--ink)", textAlign:"right", lineHeight:1 }}>{g.nodes.toLocaleString()}</div>
                  <div style={{ fontFamily:"Instrument Serif", fontSize:17, color:"var(--ink)", textAlign:"right", lineHeight:1 }}>{g.edges.toLocaleString()}</div>
                  <div style={{ fontFamily:"Instrument Serif", fontSize:17, color:"var(--ink)", textAlign:"right", lineHeight:1 }}>{g.sources}</div>
                  <div style={{ display:"flex", justifyContent:"center" }}>
                    <span style={{ display:"inline-flex", alignItems:"center", gap:6, fontFamily:"JetBrains Mono", fontSize:12, color: hColor, fontWeight:700, padding:"4px 9px", background:"var(--panel-2)", border:"1px solid " + hColor + "55", borderRadius:5 }}>
                      <span style={{ width:7, height:7, borderRadius:"50%", background: hColor }} />
                      {g.health + "%"}
                    </span>
                  </div>
                  <div style={{ display:"flex", alignItems:"center", gap:6, fontFamily:"JetBrains Mono", fontSize:11, color:"var(--ink-3)" }}>
                    <span style={{ width:5, height:5, borderRadius:"50%", background:"var(--green)" }} />
                    {g.synced}
                  </div>
                  <div style={{ display:"flex", alignItems:"center", gap:7, minWidth:0 }}>
                    <span style={{ width:22, height:22, borderRadius:4, background:"var(--ink-3)", color:"#fff", display:"inline-flex", alignItems:"center", justifyContent:"center", fontFamily:"JetBrains Mono", fontSize:8.5, fontWeight:700, flexShrink:0, letterSpacing:"0.3px" }}>{g.owner.split(/[\-\s]/).map(function(s){ return s[0]; }).join("").slice(0,2).toUpperCase()}</span>
                    <span style={{ fontFamily:"JetBrains Mono", fontSize:11, color:"var(--ink-2)", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{g.owner}</span>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {newGraphOpen && <NewGraphFlow onClose={function(){ setNewGraphOpen(false); }} onCreate={function(g){ setNewGraphOpen(false); if (g && g.id) { onOpenGraph(g.id); } else if (g && g.name && window.__openBlankGraph) { window.__openBlankGraph(g.name, g.entities || []); } }} />}
    </div>
  );
}

// Per-tab empty state — used when the current graph is blank (no nodes yet).
function WorkspaceEmpty({ icon, eyebrow, title, desc, ctaLabel, onCta, secondaryLabel, onSecondary }) {
  return (
    <div style={{ display:"flex", alignItems:"center", justifyContent:"center", padding:"40px 24px", minHeight:"calc(100vh - 200px)" }}>
      <div style={{ maxWidth: 460, textAlign:"center" }}>
        {icon && (
          <div style={{ display:"inline-flex", alignItems:"center", justifyContent:"center", width:64, height:64, borderRadius:14, background:"var(--panel)", border:"1px dashed var(--line)", marginBottom:18 }}>
            {icon}
          </div>
        )}
        {eyebrow && <div style={{ fontFamily:"JetBrains Mono", fontSize:10.5, letterSpacing:"0.6px", color:"var(--ink-3)", marginBottom:6 }}>{eyebrow}</div>}
        <div style={{ fontFamily:"'Instrument Serif', serif", fontSize:34, lineHeight:1.1, color:"var(--ink)" }}>{title}</div>
        {desc && <div style={{ fontSize:13.5, color:"var(--ink-3)", marginTop:12, lineHeight:1.55 }}>{desc}</div>}
        {(ctaLabel || secondaryLabel) && (
          <div style={{ marginTop:22, display:"inline-flex", gap:10 }}>
            {ctaLabel && <button onClick={onCta} className="btn-dark" style={{ padding:"10px 18px", fontSize:13 }}>{ctaLabel}</button>}
            {secondaryLabel && <button onClick={onSecondary} className="btn-ghost" style={{ padding:"10px 16px", fontSize:13, border:"1px solid var(--line)", borderRadius:8 }}>{secondaryLabel}</button>}
          </div>
        )}
      </div>
    </div>
  );
}

// Click-to-create blank canvas — shown when a graph has no nodes yet.
// We hide the system cursor and render our own node-disc cursor that
// follows the pointer and scales up when the user presses and holds —
// so the "drop a node here" affordance has live press feedback, not just
// a release-time ripple.
function BlankCanvas({ onAddNode }) {
  var [pos, setPos]         = React.useState({ x: 0, y: 0, inside: false });
  var [pressed, setPressed] = React.useState(false);
  var ref = React.useRef(null);

  function onMove(e){
    var r = ref.current.getBoundingClientRect();
    setPos({ x: e.clientX - r.left, y: e.clientY - r.top, inside: true });
  }
  function onLeave(){ setPos(function(p){ return { x: p.x, y: p.y, inside: false }; }); setPressed(false); }
  function onDown(){ setPressed(true); }
  function onUp(){
    if (pressed) {
      setPressed(false);
      // Hold the press a beat after release so the expanded disc registers,
      // then open the AddNodeFlow.
      setTimeout(function(){ onAddNode(); }, 120);
    }
  }

  // Scale + visual props transition from rest → press.
  var restScale = 1;
  var pressScale = 1.35;
  var scale = pressed ? pressScale : restScale;

  return (
    <div className="body">
      <main className="main" style={{ position:"relative" }}>
        <div
          ref={ref}
          onMouseMove={onMove}
          onMouseLeave={onLeave}
          onMouseDown={onDown}
          onMouseUp={onUp}
          style={{ position:"absolute", inset:0, cursor:"none", display:"flex", alignItems:"center", justifyContent:"center", background:"var(--bg-canvas)", backgroundImage:"radial-gradient(circle, #c8c0a8 0.7px, transparent 0.7px)", backgroundSize:"24px 24px", userSelect:"none" }}
        >
          <div style={{ textAlign:"center", maxWidth:460, pointerEvents:"none" }}>
            <div style={{ fontFamily:"'Instrument Serif', serif", fontSize:38, lineHeight:1.05, color:"var(--ink)" }}>Start your context graph</div>
            <div style={{ fontSize:13.5, color:"var(--ink-3)", marginTop:12, lineHeight:1.55 }}>Click anywhere on the canvas to drop your first node. Nodes can be entities, data sources, or agents — connect them with edges to model your domain.</div>
            <div style={{ marginTop:18, fontFamily:"JetBrains Mono", fontSize:11, color:"var(--ink-4)", letterSpacing:"0.4px" }}>CLICK ON GRAPH TO CREATE A NODE</div>
          </div>
          {/* Custom cursor — follows the pointer, scales up on press */}
          {pos.inside && (
            <div style={{ position:"absolute", left: pos.x, top: pos.y, width:0, height:0, pointerEvents:"none" }}>
              <div style={{ position:"absolute", left:-22, top:-22, width:44, height:44, borderRadius:"50%", background:"var(--panel)", border:"1.2px solid #bdb39a", transform: "scale(" + scale + ")", transformOrigin:"center", transition:"transform 140ms cubic-bezier(0.34, 1.56, 0.64, 1), background 140ms ease-out, border-color 140ms ease-out", display:"flex", alignItems:"center", justifyContent:"center" }}>
                <svg width="20" height="20" viewBox="0 0 20 20" style={{ display:"block" }}>
                  <line x1="10" y1="5" x2="10" y2="15" stroke="#645d4d" strokeWidth="1.8" strokeLinecap="round" />
                  <line x1="5"  y1="10" x2="15" y2="10" stroke="#645d4d" strokeWidth="1.8" strokeLinecap="round" />
                </svg>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

function App() {
  // null = show landing; "ecg" or other graph id = inside that graph
  const [currentGraphId, setCurrentGraphId] = useState(null);
  const [tab, setTab] = useState("Graph");
  const [detailId, setDetailId] = useState(null);
  const [addNodeOpen, setAddNodeOpen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [filter, setFilter] = useState("all");
  const [query, setQuery] = useState("");
  const [stewardshipRuleFilter, setStewardshipRuleFilter] = useState(null);
  // Expose a global deeplink: clicking "9 violations" anywhere navigates here
  // and pre-filters the steward queue to that rule's tasks.
  React.useEffect(function(){
    window.__goToStewardship = function(ruleTitle){
      setDetailId(null);
      setTab("Violations");
      setStewardshipRuleFilter(ruleTitle || null);
    };
    return function(){ delete window.__goToStewardship; };
  }, []);
  const [selected, setSelected] = useState("account");
  const [hover, setHover] = useState(null);
  const [savedView, setSavedView] = useState("Full schema");
  const [showInferred,  setShowInferred]  = useState(true);
  const [showEdgeLabels, setShowEdgeLabels] = useState(true);
  const [showCounts,    setShowCounts]    = useState(true);
  const [viewport, setViewport] = useState({ zoom: 0.95, panX: 0, panY: 0 });
  const [nodes, setNodes] = useState(NODES.filter(n => n.type !== "agent"));
  const [edges, setEdges] = useState(EDGES);
  const [blankGraphName, setBlankGraphName] = useState(null); // when set, this graph is in blank-mode
  // Blank mode is only "on" while the graph really is empty. Once the user
  // creates their first node, we exit the empty-state shell and render the
  // real canvas + workspace tabs.
  const isBlank = blankGraphName !== null && nodes.length === 0;
  const canvasSize = useRef({ w: 1000, h: 700 });

  // ─── EDIT MODE ─────────────────────────────────────────────────────────────
  // When on, the canvas accepts: click-empty → add node (position pre-set),
  // drag from a node's connector handle → create edge, click a node/edge →
  // open its editor, hover × → delete. Every change applies live to nodes/edges
  // state so there's no separate Save / Discard step — exiting just turns the
  // edit affordances off.
  const [editMode, setEditMode] = useState(false);
  // Cursor mode while in edit:
  //   "add"    — dashed-plus canvas cursor on empty canvas, click drops a node.
  //   "select" — regular grab/pointer, click empty space just deselects (pan).
  // Users who want to pan/inspect without adding nodes flip this to "select".
  const [cursorMode, setCursorMode] = useState("add");
  // Multi-selected node ids — populated by marquee select or shift-click.
  const [multiSelected, setMultiSelected] = useState([]);
  // Undo / redo history. Each entry: { nodes, edges }. We snapshot before any
  // mutating action; refs mirror current nodes/edges so undo/redo callbacks
  // can read the latest values without going stale.
  const historyRef = useRef({ past: [], future: [] });
  const nodesRef = useRef(nodes);
  const edgesRef = useRef(edges);
  useEffect(() => { nodesRef.current = nodes; }, [nodes]);
  useEffect(() => { edgesRef.current = edges; }, [edges]);
  // Bump to force re-render of undo/redo button enabled states.
  const [historyTick, setHistoryTick] = useState(0);

  function pushHistory() {
    historyRef.current.past.push({
      nodes: nodesRef.current.map(function(n){ return Object.assign({}, n); }),
      edges: edgesRef.current.map(function(e){ return Object.assign({}, e); }),
    });
    if (historyRef.current.past.length > 60) historyRef.current.past.shift();
    historyRef.current.future = [];
    setHistoryTick(function(t){ return t + 1; });
  }
  function undo() {
    var past = historyRef.current.past;
    if (past.length === 0) return;
    historyRef.current.future.push({
      nodes: nodesRef.current.map(function(n){ return Object.assign({}, n); }),
      edges: edgesRef.current.map(function(e){ return Object.assign({}, e); }),
    });
    var snap = past.pop();
    setNodes(snap.nodes);
    setEdges(snap.edges);
    setHistoryTick(function(t){ return t + 1; });
  }
  function redo() {
    var future = historyRef.current.future;
    if (future.length === 0) return;
    historyRef.current.past.push({
      nodes: nodesRef.current.map(function(n){ return Object.assign({}, n); }),
      edges: edgesRef.current.map(function(e){ return Object.assign({}, e); }),
    });
    var snap = future.pop();
    setNodes(snap.nodes);
    setEdges(snap.edges);
    setHistoryTick(function(t){ return t + 1; });
  }
  function duplicateSelected() {
    var ids = multiSelected.length > 0 ? multiSelected
            : (selected ? [selected] : []);
    if (ids.length === 0) return;
    pushHistory();
    var newIds = [];
    setNodes(function(ns){
      var existingIds = ns.map(function(n){ return n.id; });
      var out = ns.slice();
      ids.forEach(function(id){
        var src = ns.find(function(n){ return n.id === id; });
        if (!src) return;
        // Unique id by appending -copy / -copyN
        var base = src.id + "-copy";
        var nid = base, k = 2;
        while (existingIds.indexOf(nid) >= 0) { nid = base + k; k++; }
        existingIds.push(nid);
        var clone = Object.assign({}, src, {
          id: nid,
          x: (src.x || 0) + 40,
          y: (src.y || 0) + 40,
          label: src.label,
        });
        newIds.push(nid);
        out.push(clone);
      });
      return out;
    });
    setMultiSelected(newIds);
  }
  // Open the impact-aware delete confirmation. Building the impact summary
  // is cheap so we do it inline.
  const [pendingDelete, setPendingDelete] = useState(null); // { ids: [...] }
  function deleteSelected() {
    var ids = multiSelected.length > 0 ? multiSelected
            : (selected ? [selected] : []);
    if (ids.length === 0) return;
    setPendingDelete({ ids: ids.slice() });
  }
  function commitDelete(ids) {
    pushHistory();
    var idSet = {};
    ids.forEach(function(id){ idSet[id] = true; });
    setNodes(function(ns){ return ns.filter(function(n){ return !idSet[n.id]; }); });
    setEdges(function(es){ return es.filter(function(e){ return !idSet[e.s] && !idSet[e.t]; }); });
    setMultiSelected([]);
    if (selected && idSet[selected]) setSelected(null);
    setPendingDelete(null);
  }

  // Edit-mode keyboard shortcuts.
  useEffect(function(){
    if (!editMode) return;
    function onKey(e){
      // Skip when the user is typing in an input/textarea/contenteditable.
      var tag = e.target && e.target.tagName;
      if (tag === "INPUT" || tag === "TEXTAREA" || (e.target && e.target.isContentEditable)) return;
      var meta = e.metaKey || e.ctrlKey;
      if (meta && e.key.toLowerCase() === "z") {
        e.preventDefault();
        if (e.shiftKey) redo(); else undo();
      } else if (meta && (e.key === "y" || e.key === "Y")) {
        e.preventDefault(); redo();
      } else if (meta && (e.key === "d" || e.key === "D")) {
        e.preventDefault(); duplicateSelected();
      } else if (e.key === "Delete" || e.key === "Backspace") {
        if (multiSelected.length > 0 || selected) {
          e.preventDefault(); deleteSelected();
        }
      }
    }
    window.addEventListener("keydown", onKey);
    return function(){ window.removeEventListener("keydown", onKey); };
  }, [editMode, multiSelected, selected]);
  // { fromId, toId, editIdx?, initialLabel? } — set when a drag completes or
  // when an existing edge is clicked for edit. editIdx tells the onCreate
  // callback to splice the existing edge instead of appending.
  const [pendingEdgeFrom, setPendingEdgeFrom] = useState(null);
  const [pendingAddPos, setPendingAddPos] = useState(null);     // { x, y } world coords for next created node

  function enterEditMode() {
    setEditMode(true);
    // Give the canvas room to work — close the inspector and collapse the
    // sidebar so the editable surface isn't squeezed between two panels.
    setSelected(null);
    setSidebarOpen(false);
  }
  function exitEditMode() {
    setEditMode(false);
    // Re-open the node sidebar — users coming back to View mode usually want
    // the navigator visible again.
    setSidebarOpen(true);
  }

  // Build a starter node for each entity name a template supplies. Each node
  // lands with a sensible default property set (id / name / created_at /
  // updated_at), positioned around the origin so it's easy to see the
  // whole graph at a glance.
  function buildTemplateNodes(entityNames) {
    if (!entityNames || !entityNames.length) return [];
    var N = entityNames.length;
    var R = Math.max(160, N * 18);
    var ts = Date.now().toString(36).slice(-4);
    return entityNames.map(function(name, i){
      var angle = (i / N) * 2 * Math.PI - Math.PI / 2;
      var slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "") || ("node_" + i);
      var keyName = slug + "_id";
      return {
        id: slug + "-" + ts + "-" + i,
        label: name,
        type: "entity",
        cat: "core",
        x: Math.round(Math.cos(angle) * R),
        y: Math.round(Math.sin(angle) * R),
        props: 4,
        edges: 0,
        glyph: null,
        glyphImage: null,
        size: 22,
        _userProps: [
          { name: keyName,     type: "uuid",      required: true, indexed: true,  pii: false, pk: true,  fill: 100, conf: 100, source: "primary" },
          { name: "name",       type: "string",    required: true, indexed: true,  pii: false,            fill: 100, conf: 100, source: "primary" },
          { name: "created_at", type: "timestamp", required: true, indexed: true,  pii: false,            fill: 100, conf: 100, source: "primary" },
          { name: "updated_at", type: "timestamp", required: true, indexed: false, pii: false,            fill: 100, conf: 100, source: "primary" },
        ],
        instances: "—", instancesN: 0,
        fill: 0, conf: 0, pii: 0, fresh: "—", change: "LOW",
      };
    });
  }

  // Common entity relationships — when both endpoints exist in a template,
  // we drop a starter edge between them so the user sees a connected graph
  // instead of a ring of unrelated nodes.
  var TEMPLATE_EDGES = [
    // Commerce / pipeline
    { from:"Customer", to:"Account",        label:"OWNS" },
    { from:"Customer", to:"Contact",        label:"HAS_CONTACT" },
    { from:"Customer", to:"Order",          label:"PLACED" },
    { from:"Customer", to:"Case",           label:"RAISED" },
    { from:"Customer", to:"Subscription",   label:"SUBSCRIBES_TO" },
    { from:"Account",  to:"Subscription",   label:"HAS_SUBSCRIPTION" },
    { from:"Account",  to:"Contract",       label:"GOVERNED_BY" },
    { from:"Account",  to:"Opportunity",    label:"HAS_OPPORTUNITY" },
    { from:"Lead",     to:"Opportunity",    label:"CONVERTS_TO" },
    { from:"Lead",     to:"Contact",        label:"MATCHES" },
    { from:"Opportunity", to:"Quote",       label:"PRODUCES" },
    { from:"Quote",    to:"Order",          label:"BECOMES" },
    { from:"Order",    to:"Product",        label:"INCLUDES" },
    { from:"Order",    to:"Shipment",       label:"SHIPS_AS" },
    { from:"Order",    to:"Invoice",        label:"BILLED_AS" },
    { from:"Order",    to:"Return",         label:"RETURNED_AS" },
    { from:"Subscription", to:"Invoice",    label:"BILLS" },
    { from:"Invoice",  to:"Payment",        label:"PAID_BY" },
    { from:"Product",  to:"Inventory",      label:"TRACKED_IN" },
    { from:"Product",  to:"Price List Item",label:"PRICED_AS" },
    // Retail
    { from:"Store",    to:"Inventory",      label:"STOCKS" },
    { from:"Store",    to:"Employee",       label:"EMPLOYS" },
    { from:"Loyalty Account", to:"Customer", label:"REWARDS" },
    { from:"Promotion",to:"Product",        label:"APPLIES_TO" },
    // Service
    { from:"Case",     to:"Case Resolution", label:"RESOLVED_BY" },
    { from:"Case",     to:"Entitlement",    label:"COVERS" },
    { from:"Case",     to:"Knowledge Article",label:"REFERENCES" },
    { from:"Case",     to:"Queue",          label:"QUEUED_IN" },
    { from:"Case",     to:"SLA",            label:"GOVERNED_BY" },
    { from:"Contact",  to:"Account",        label:"WORKS_AT" },
    { from:"Renewal",  to:"Account",        label:"RENEWS" },
    { from:"Health Score", to:"Customer",   label:"SCORES" },
    // HR / org
    { from:"Employee", to:"Team",           label:"BELONGS_TO" },
    { from:"Employee", to:"Role",           label:"HAS_ROLE" },
    { from:"Employee", to:"Position",       label:"FILLS" },
    { from:"Employee", to:"Department",     label:"REPORTS_TO" },
    { from:"Employee", to:"Compensation",   label:"PAID_AS" },
    { from:"Employee", to:"Manager Chain",  label:"REPORTS_VIA" },
    { from:"Worker",   to:"Position",       label:"HOLDS" },
    { from:"Position", to:"Job",            label:"DEFINED_BY" },
    { from:"Employee", to:"Tenure",         label:"ACCRUES" },
    { from:"Employee", to:"Device",         label:"ASSIGNED" },
    { from:"Employee", to:"Access Grant",   label:"GRANTED" },
    { from:"Employee", to:"Pay Cycle",      label:"PAID_VIA" },
    // Marketing
    { from:"Campaign", to:"Marketing List", label:"TARGETS" },
    { from:"Campaign", to:"Marketing Email",label:"SENDS" },
    { from:"Campaign", to:"Customer Journey", label:"TRIGGERS" },
    { from:"Customer Journey", to:"Segment",label:"BELONGS_TO" },
    { from:"Marketing List", to:"Lead",     label:"INCLUDES" },
    { from:"Marketing Form", to:"Lead",     label:"CAPTURES" },
    { from:"Interaction", to:"Customer",    label:"INVOLVES" },
    // Finance
    { from:"Journal Entry", to:"GL Account",label:"POSTS_TO" },
    { from:"Invoice",  to:"GL Account",     label:"BOOKED_TO" },
    { from:"Payment",  to:"GL Account",     label:"SETTLED_TO" },
    { from:"Policy",   to:"Control",        label:"ENFORCES" },
    // Supply chain
    { from:"Purchase Order", to:"Supplier", label:"ISSUED_TO" },
    { from:"Purchase Order", to:"Item",     label:"ORDERS" },
    { from:"Item",     to:"BOM",            label:"COMPOSED_OF" },
    { from:"Item",     to:"Inventory",      label:"TRACKED_IN" },
    { from:"Plant",    to:"Inventory",      label:"HOLDS" },
    // Healthcare
    { from:"Patient",  to:"Encounter",      label:"ATTENDED" },
    { from:"Encounter",to:"Condition",      label:"DIAGNOSED" },
    { from:"Encounter",to:"Procedure",      label:"PERFORMED" },
    { from:"Encounter",to:"Observation",    label:"OBSERVED" },
    { from:"Patient",  to:"Medication",     label:"PRESCRIBED" },
    { from:"Patient",  to:"Allergy Intolerance", label:"HAS" },
    { from:"Patient",  to:"Care Plan",      label:"FOLLOWS" },
    { from:"Encounter",to:"Diagnostic Report", label:"REPORTED" },
    { from:"Provider", to:"Practitioner Role",label:"HAS_ROLE" },
    { from:"Encounter",to:"Provider",       label:"ATTENDED_BY" },
    { from:"Claim",    to:"Encounter",      label:"SUBMITTED_FOR" },
    // Banking
    { from:"Customer", to:"Bank",           label:"BANKS_WITH" },
    { from:"Customer", to:"Financial Product", label:"HOLDS" },
    { from:"Customer", to:"KYC Case",       label:"SUBJECT_OF" },
    { from:"Account",  to:"Branch",         label:"OPENED_AT" },
    { from:"Account",  to:"Transaction",    label:"RECORDS" },
    { from:"Transaction", to:"Hold",        label:"HAS_HOLD" },
    { from:"Mortgage Application", to:"Collateral", label:"BACKED_BY" },
    { from:"Mortgage Application", to:"Customer", label:"FILED_BY" },
    { from:"Compliance Case", to:"Customer", label:"INVESTIGATES" },
  ];

  function buildTemplateEdges(entityNames, nodes) {
    if (!entityNames || !entityNames.length) return [];
    // Map entity label → node id for quick lookup
    var byLabel = {};
    nodes.forEach(function(n){ byLabel[n.label] = n.id; });
    var present = {};
    entityNames.forEach(function(name){ present[name] = true; });
    var out = [];
    TEMPLATE_EDGES.forEach(function(e){
      if (present[e.from] && present[e.to] && byLabel[e.from] && byLabel[e.to]) {
        out.push({ s: byLabel[e.from], t: byLabel[e.to], label: e.label, kind: "direct" });
      }
    });
    return out;
  }

  // Expose a global opener used by the landing-page NewGraphFlow.onCreate.
  // When entities are supplied (template path) we pre-seed the graph with a
  // ring of starter nodes + canonical edges between them.
  React.useEffect(function(){
    window.__openBlankGraph = function(name, entities){
      var seedNodes = buildTemplateNodes(entities || []);
      var seedEdges = buildTemplateEdges(entities || [], seedNodes);
      setBlankGraphName(name || "Untitled graph");
      setNodes(seedNodes);
      setEdges(seedEdges);
      setSelected(null);
      setDetailId(null);
      setTab("Graph");
      setCurrentGraphId("blank-" + Date.now());
    };
    return function(){ delete window.__openBlankGraph; };
  }, []);

  const selectedNode = nodes.find(n => n.id === selected);

  // keyboard
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "Escape") setSelected(null);
      if ((e.metaKey || e.ctrlKey) && e.key === "f") { e.preventDefault(); document.querySelector(".sb-search input")?.focus(); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // Landing screen: pre-graph workspace picker
  if (!currentGraphId) {
    return (
      <div className="app">
        <GraphLandingView onOpenGraph={function(id){
          setCurrentGraphId(id);
          setTab("Graph");
          setDetailId(null);
          setBlankGraphName(null);
          setNodes(NODES.filter(function(n){ return n.type !== "agent"; }));
          // Always land in View mode when entering a graph from the landing.
          setEditMode(false);
          setSidebarOpen(true);
        }} />
      </div>
    );
  }

  var currentGraph = CONTEXT_GRAPHS.find(function(g){ return g.id === currentGraphId; });
  var graphName = currentGraph ? currentGraph.name : (isBlank ? blankGraphName : (IS_PS_GRAPH ? "Product Specialist Graph" : "Enterprise Context Graph"));

  return (
    <div className="app">
      <Header tab={tab} onTab={(t) => { setTab(t); setDetailId(null); }} onAddNode={() => setAddNodeOpen(true)} onBackToLanding={() => setCurrentGraphId(null)} graphName={graphName} />
      {detailId ? (
        <NodeDetailView
          nodeId={detailId}
          nodes={nodes}
          edges={edges}
          onBack={() => setDetailId(null)}
          onCanvas={() => { setSelected(detailId); setTab("Graph"); setDetailId(null); }}
        />
      ) : isBlank && tab === "Nodes" ? (
        <WorkspaceEmpty
          eyebrow="NODES"
          title="No nodes yet"
          desc="Nodes represent entities, data sources, or agents in your graph. Add the first one to start modelling your domain."
          ctaLabel="+ Add node"
          onCta={function(){ setAddNodeOpen(true); }}
          secondaryLabel="Open canvas"
          onSecondary={function(){ setTab("Graph"); }}
          icon={<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="var(--ink-3)" strokeWidth="1.5"><circle cx="12" cy="12" r="6"/></svg>}
        />
      ) : tab === "Nodes" ? (
        <NodesView
          nodes={nodes}
          onSelect={(id) => { setDetailId(id); }}
          onSwitchToCanvas={() => setTab("Graph")}
          onAddNode={() => setAddNodeOpen(true)}
        />
      ) : isBlank && tab === "Edges" ? (
        <WorkspaceEmpty
          eyebrow="EDGES"
          title="No edges yet"
          desc="Edges define relationships between nodes — :WORKS_AT, :GOVERNED_BY, :OBSERVED_ON. Add nodes first, then connect them."
          ctaLabel="+ Add node"
          onCta={function(){ setAddNodeOpen(true); }}
          icon={<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="var(--ink-3)" strokeWidth="1.5"><circle cx="6" cy="12" r="3"/><circle cx="18" cy="12" r="3"/><line x1="9" y1="12" x2="15" y2="12" strokeDasharray="2 2"/></svg>}
        />
      ) : tab === "Edges" ? (
        <GlobalEdgesView nodes={nodes} edges={edges} />
      ) : isBlank && tab === "Sources" ? (
        <WorkspaceEmpty
          eyebrow="SOURCES"
          title="No sources connected"
          desc="Connect data sources — Salesforce, NetSuite, Snowflake, Okta — to populate nodes with real records and lineage."
          ctaLabel="+ Connect source"
          onCta={function(){ setAddNodeOpen(true); }}
          icon={<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="var(--ink-3)" strokeWidth="1.5"><ellipse cx="12" cy="6" rx="7" ry="2.5"/><path d="M5 6v6c0 1.4 3.1 2.5 7 2.5s7-1.1 7-2.5V6"/><path d="M5 12v6c0 1.4 3.1 2.5 7 2.5s7-1.1 7-2.5v-6"/></svg>}
        />
      ) : tab === "Sources" ? (
        <GlobalSourcesView />
      ) : isBlank && tab === "Records" ? (
        <WorkspaceEmpty
          eyebrow="RECORDS"
          title="No records to browse"
          desc="Records are the actual rows behind each node. They appear here once you connect a source and let it sync."
          icon={<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="var(--ink-3)" strokeWidth="1.5"><rect x="4" y="5" width="16" height="14" rx="2"/><line x1="4" y1="10" x2="20" y2="10"/><line x1="9" y1="10" x2="9" y2="19"/></svg>}
        />
      ) : tab === "Records" ? (
        <RecordsView />
      ) : isBlank && tab === "Violations" ? (
        <WorkspaceEmpty
          eyebrow="VIOLATIONS"
          title="No violations — no rules yet"
          desc="Once you define quality, match, or survivorship rules on your nodes, any failing rows will show up here for stewards to action."
          icon={<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="var(--ink-3)" strokeWidth="1.5"><path d="M12 3l9 16H3l9-16z"/><line x1="12" y1="9" x2="12" y2="14"/><circle cx="12" cy="17" r="0.8" fill="var(--ink-3)"/></svg>}
        />
      ) : tab === "Violations" ? (
        <StewardshipView initialRuleFilter={stewardshipRuleFilter} onClearRuleFilter={function(){ setStewardshipRuleFilter(null); }} />
      ) : isBlank && tab === "Governance" ? (
        <WorkspaceEmpty
          eyebrow="GOVERNANCE"
          title="Governance starts with nodes"
          desc="Policies, retention rules, roles, and compliance frameworks attach to entities. Add your first node to begin governing it."
          ctaLabel="+ Add node"
          onCta={function(){ setAddNodeOpen(true); }}
          icon={<svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="var(--ink-3)" strokeWidth="1.5"><path d="M12 3l8 4v6c0 4.5-3.5 7.5-8 8-4.5-.5-8-3.5-8-8V7l8-4z"/></svg>}
        />
      ) : tab === "Governance" ? (
        <GovernanceWorkspace />
      ) : isBlank && tab === "Graph" ? (
        <BlankCanvas onAddNode={function(){ setAddNodeOpen(true); }} />
      ) : tab !== "Graph" ? (
        <div className="placeholder-view">
          <div className="ph-eyebrow">SCHEMA · {tab.toUpperCase()}</div>
          <div className="ph-title">{tab}</div>
          <div className="ph-desc">This view is under construction. Switch to <button className="ph-link" onClick={() => setTab("Graph")}>Graph</button> or <button className="ph-link" onClick={() => setTab("Nodes")}>Nodes</button>.</div>
        </div>
      ) : (
      <div className="body">
        <Sidebar
          open={sidebarOpen}
          onToggle={() => setSidebarOpen(o => !o)}
          filter={filter} setFilter={setFilter}
          query={query} setQuery={setQuery}
          selected={selected} onSelect={(id) => { setSelected(id); }}
          hover={hover} setHover={setHover}
          savedView={savedView} setSavedView={setSavedView}
        />
        <main className="main">
          <div className="canvas-toolbar">
            <div className="ctb-left">
              <span className="ctb-chip">SELECTION</span>
              <span className="ctb-val">{selectedNode ? selectedNode.label : "—"}</span>
              <span className="ctb-tag">{selectedNode ? TYPE_META[selectedNode.type].tag.toLowerCase() : "none"}</span>
            </div>
            <div className="ctb-right">
              <label className="ctb-toggle"><input type="checkbox" checked={showInferred} onChange={(e) => setShowInferred(e.target.checked)} /> <span>Inferred</span></label>
              <label className="ctb-toggle"><input type="checkbox" checked={showEdgeLabels} onChange={(e) => setShowEdgeLabels(e.target.checked)} /> <span>Edge labels</span></label>
              <label className="ctb-toggle"><input type="checkbox" checked={showCounts} onChange={(e) => setShowCounts(e.target.checked)} /> <span>Counts</span></label>
            </div>
          </div>
          <Canvas
            nodes={nodes} setNodes={setNodes}
            edges={edges} setEdges={setEdges}
            selected={selected} setSelected={setSelected}
            hover={hover} setHover={setHover}
            filter={filter} query={query} savedView={savedView}
            viewport={viewport} setViewport={setViewport}
            sidebarOpen={sidebarOpen}
            showInferred={showInferred} showEdgeLabels={showEdgeLabels} showCounts={showCounts}
            editMode={editMode}
            cursorMode={cursorMode}
            multiSelected={multiSelected}
            setMultiSelected={setMultiSelected}
            pushHistory={pushHistory}
            onEditAdd={function(worldX, worldY){ setPendingAddPos({ x: worldX, y: worldY }); setAddNodeOpen(true); }}
            onEditConnect={function(fromId, toId){ setPendingEdgeFrom({ fromId: fromId, toId: toId }); }}
            onEditOpenNode={function(id){ setDetailId(id); setTab("Nodes"); }}
            onEditEdge={function(idx){
              var e = edges[idx];
              if (!e) return;
              setPendingEdgeFrom({ fromId: e.s, toId: e.t, editIdx: idx, initialLabel: e.label || "" });
            }}
          />
          <Legend filter={filter} setFilter={setFilter} />
          <div className="bottomright">
            <Minimap nodes={nodes} viewport={viewport} size={{ w: 1100, h: 700 }} />
            <ZoomControls viewport={viewport} setViewport={setViewport} nodes={nodes} size={{ w: 1100, h: 700 }} />
          </div>
          {/* View / Edit segmented toggle — floating pill, top-center of the
              canvas. Active segment slides into the ink-filled state. */}
          <ViewEditToggle
            editMode={editMode}
            onEnter={enterEditMode}
            onExit={exitEditMode}
            cursorMode={cursorMode}
            setCursorMode={setCursorMode}
            canUndo={historyRef.current.past.length > 0}
            canRedo={historyRef.current.future.length > 0}
            onUndo={undo}
            onRedo={redo}
            onDuplicate={duplicateSelected}
            canDuplicate={multiSelected.length > 0 || !!selected}
            onDelete={deleteSelected}
            canDelete={multiSelected.length > 0 || !!selected}
          />
        </main>
        {selectedNode && <Inspector node={selectedNode} edges={edges} nodes={nodes} onClose={() => setSelected(null)} onOpenDetail={() => { setDetailId(selectedNode.id); setTab("Nodes"); }} />}
      </div>
      )}
      {addNodeOpen && <AddNodeFlow onClose={function(){ setAddNodeOpen(false); setPendingAddPos(null); }} onCreate={function(spec){
        pushHistory();
        // Build a minimal node from the flow output. If the user clicked the
        // canvas at a specific world position (edit-mode add), drop the node
        // there; otherwise jitter near the centre.
        var id = (spec.name || "node").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || ("node-" + Date.now());
        var px, py;
        if (pendingAddPos) {
          px = pendingAddPos.x; py = pendingAddPos.y;
        } else {
          var jitter = nodes.length * 80;
          px = (jitter % 400) - 200;
          py = Math.floor(jitter / 400) * 120 - 60;
        }
        var userProps = (spec.properties && spec.properties.length) ? spec.properties.slice() : [];
        // Map the user's chosen category to the workspace's filter buckets so
        // the new node shows up correctly in Nodes view counts.
        var catMap = { core: "core", secondary: "support", derived: "derived" };
        var cat = catMap[spec.category] || "core";
        var newNode = {
          id: id + "-" + Date.now().toString(36).slice(-4),
          label: spec.name || "New node",
          type: spec.shape || "entity",
          cat: cat,
          x: px,
          y: py,
          props: userProps.length,
          edges: 0,
          glyph: spec.glyph || null,
          glyphImage: spec.glyphImage || null,
          size: 22,
          // Carry the full property definitions so the Inspector + NodeDetailView
          // render them in the Properties tab instead of the synthesized fakes.
          _userProps: userProps,
          // Display the entered description in the detail/inspector view too.
          _description: spec.description || "",
          instances: "—",
          instancesN: 0,
          fill: 0, conf: 0, pii: 0, fresh: "—", change: "LOW",
        };
        setNodes(function(ns){ return ns.concat([newNode]); });
        setSelected(newNode.id);
        setPendingAddPos(null);
      }} />}
      {/* Edge-create / edge-edit flow.
          Triggered by an edit-mode drag from a node handle (no editIdx) or by
          clicking an existing edge in edit mode (editIdx set). The same flow
          serves both — onCreate either appends a new edge or splices the
          existing one in place. */}
      {pendingEdgeFrom && (
        <NewEdgeFlow
          nodes={nodes}
          fromNode={nodes.find(function(n){ return n.id === pendingEdgeFrom.fromId; })}
          toNode={nodes.find(function(n){ return n.id === pendingEdgeFrom.toId; })}
          initialLabel={pendingEdgeFrom.initialLabel || ""}
          onClose={function(){ setPendingEdgeFrom(null); }}
          onCreate={function(spec){
            var s = spec && spec.from && spec.from.id;
            var t = spec && spec.to && spec.to.id;
            var lbl = (spec.label || "RELATES").toUpperCase();
            var editIdx = pendingEdgeFrom.editIdx;
            if (s && t) {
              pushHistory();
              if (editIdx !== undefined && editIdx !== null) {
                setEdges(function(es){ return es.map(function(edge, i){ return i === editIdx ? Object.assign({}, edge, { s: s, t: t, label: lbl }) : edge; }); });
              } else {
                setEdges(function(es){ return es.concat([{ s: s, t: t, label: lbl, kind: "direct" }]); });
              }
            }
            setPendingEdgeFrom(null);
          }}
        />
      )}
      {/* Delete impact dialog — fired when the user presses Delete/Backspace
          (or clicks a future delete action) with one or more nodes selected. */}
      {pendingDelete && (
        <DeleteImpactDialog
          ids={pendingDelete.ids}
          nodes={nodes}
          edges={edges}
          onCancel={function(){ setPendingDelete(null); }}
          onConfirm={function(){ commitDelete(pendingDelete.ids); }}
        />
      )}
    </div>
  );
}

// ─── DELETE IMPACT DIALOG ───────────────────────────────────────────────────
// Two-step destructive confirmation:
//   Step 1 — Review impact (KPI strip, edge list, neighbour pills)
//   Step 2 — Type confirmation: the node name (single) or "DELETE" (multi)
// The user has to deliberately move through both steps to commit. Cancel
// is always one tap away.
function DeleteImpactDialog({ ids, nodes, edges, onCancel, onConfirm }) {
  var idSet = {}; ids.forEach(function(id){ idSet[id] = true; });
  var targetNodes = nodes.filter(function(n){ return idSet[n.id]; });
  var affectedEdges = edges.filter(function(e){ return idSet[e.s] || idSet[e.t]; });
  // Neighbour nodes that will lose at least one connection (not the targets themselves)
  var neighbourIds = {};
  affectedEdges.forEach(function(e){
    if (idSet[e.s] && !idSet[e.t]) neighbourIds[e.t] = true;
    if (idSet[e.t] && !idSet[e.s]) neighbourIds[e.s] = true;
  });
  var neighbours = nodes.filter(function(n){ return neighbourIds[n.id]; });
  // Sum of records (instancesN) that get unreachable from this graph
  var totalRecords = targetNodes.reduce(function(acc, n){ return acc + (n.instancesN || 0); }, 0);
  // Sum of property fields across all targets
  var totalProps = targetNodes.reduce(function(acc, n){ return acc + (n.props || 0); }, 0);
  var multi = ids.length > 1;

  // Confirmation phrase: node name for single, "DELETE" for multi.
  var requiredPhrase = multi ? "DELETE" : (targetNodes[0] ? targetNodes[0].label : "DELETE");
  var [step, setStep] = useState(1);
  var [typed, setTyped] = useState("");
  var [ack, setAck] = useState(false);
  var canContinue = step === 1 ? ack : (typed.trim() === requiredPhrase);

  function fmtNum(n){ return n >= 1000 ? (n / 1000).toFixed(n >= 10000 ? 0 : 1) + "K" : String(n); }

  return (
    <div onClick={function(e){ if (e.target === e.currentTarget) onCancel(); }}
      style={{ position:"fixed", top:0, left:0, right:0, bottom:0, background:"rgba(0,0,0,0.45)", zIndex:300, display:"flex", alignItems:"center", justifyContent:"center" }}>
      <div style={{ width:"min(94vw, 580px)", maxHeight:"88vh", overflow:"auto", background:"var(--bg-canvas)", borderRadius:14, border:"1px solid var(--line)", boxShadow:"0 32px 80px rgba(0,0,0,0.32)" }}>
        {/* Header */}
        <div style={{ padding:"24px 26px 4px" }}>
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:12 }}>
            <div style={{ display:"inline-flex", alignItems:"center", gap:6, padding:"3px 9px", borderRadius:4, background:"var(--coral-fill)", color:"var(--coral)", fontFamily:"JetBrains Mono", fontSize:10, fontWeight:700, letterSpacing:"0.5px", textTransform:"uppercase" }}>
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 3l9 16H3l9-16z"/><line x1="12" y1="10" x2="12" y2="14"/><circle cx="12" cy="17" r="0.6" fill="currentColor"/></svg>
              Destructive action
            </div>
            <div style={{ fontFamily:"JetBrains Mono", fontSize:10, color:"var(--ink-3)", letterSpacing:"0.5px", textTransform:"uppercase" }}>Step {step} of 2 · {step === 1 ? "Review impact" : "Confirm"}</div>
          </div>
          <div style={{ fontFamily:"'Instrument Serif', serif", fontSize:28, color:"var(--ink)", lineHeight:1.1, marginBottom:8 }}>
            {multi ? ("Delete " + ids.length + " nodes?") : (
              targetNodes[0] ? <>Delete <strong>{targetNodes[0].label}</strong>?</> : "Delete node?"
            )}
          </div>
          <div style={{ fontSize:13, color:"var(--ink-3)", lineHeight:1.55 }}>
            This will remove {multi ? "these nodes" : "this node"} from the schema along with every edge connected to {multi ? "them" : "it"}. Downstream computations and rules that reference {multi ? "these" : "this"} entity types will break.
          </div>
        </div>

        {step === 1 && (<>
          {/* Impact summary — 4 KPI cells */}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(4, 1fr)", gap:0, margin:"18px 26px 0", border:"1px solid var(--line)", borderRadius:10, overflow:"hidden", background:"var(--panel)" }}>
            {[
              { k:"NODES",      v: ids.length },
              { k:"EDGES",      v: affectedEdges.length },
              { k:"PROPERTIES", v: totalProps },
              { k:"RECORDS",    v: fmtNum(totalRecords) }
            ].map(function(cell, i, arr){
              return (
                <div key={i} style={{ padding:"12px 14px", borderRight: i < arr.length-1 ? "1px solid var(--line-2)" : "none" }}>
                  <div style={{ fontFamily:"JetBrains Mono", fontSize:9.5, letterSpacing:"0.5px", color:"var(--ink-3)", textTransform:"uppercase", marginBottom:4 }}>{cell.k}</div>
                  <div style={{ fontFamily:"'Instrument Serif', serif", fontSize:22, color:"var(--ink)", lineHeight:1 }}>{cell.v}</div>
                </div>
              );
            })}
          </div>

          {/* Affected nodes list (multi) */}
          {multi && targetNodes.length > 0 && (
            <div style={{ margin:"18px 26px 0" }}>
              <div style={{ fontFamily:"JetBrains Mono", fontSize:9.5, letterSpacing:"0.5px", color:"var(--ink-3)", textTransform:"uppercase", marginBottom:8 }}>Nodes being deleted</div>
              <div style={{ background:"var(--panel)", border:"1px solid var(--line)", borderRadius:8, padding:"4px 0", maxHeight:140, overflow:"auto" }}>
                {targetNodes.map(function(n, i, arr){
                  return (
                    <div key={n.id} style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"7px 14px", borderBottom: i < arr.length-1 ? "1px dashed var(--line-2)" : "none" }}>
                      <div style={{ display:"flex", alignItems:"center", gap:8, minWidth:0 }}>
                        <ListGlyph node={n} size={14} />
                        <span style={{ fontSize:12.5, color:"var(--ink)", whiteSpace:"nowrap", overflow:"hidden", textOverflow:"ellipsis" }}>{n.label}</span>
                        <span style={{ fontFamily:"JetBrains Mono", fontSize:9.5, color:"var(--ink-4)", textTransform:"uppercase" }}>{n.type}</span>
                      </div>
                      <span style={{ fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-3)" }}>{n.instances || "—"}</span>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* Edges being severed */}
          {affectedEdges.length > 0 && (
            <div style={{ margin:"18px 26px 0" }}>
              <div style={{ fontFamily:"JetBrains Mono", fontSize:9.5, letterSpacing:"0.5px", color:"var(--ink-3)", textTransform:"uppercase", marginBottom:8 }}>Edges severed ({affectedEdges.length})</div>
              <div style={{ background:"var(--panel)", border:"1px solid var(--line)", borderRadius:8, padding:"4px 0", maxHeight:160, overflow:"auto" }}>
                {affectedEdges.slice(0, 8).map(function(e, i, arr){
                  var s = nodes.find(function(n){ return n.id === e.s; });
                  var t = nodes.find(function(n){ return n.id === e.t; });
                  return (
                    <div key={i} style={{ display:"flex", alignItems:"center", gap:6, padding:"7px 14px", borderBottom: i < Math.min(arr.length, 8) - 1 ? "1px dashed var(--line-2)" : "none", fontFamily:"JetBrains Mono", fontSize:11, color:"var(--ink-2)" }}>
                      <span style={{ color: idSet[e.s] ? "var(--coral)" : "var(--ink-3)" }}>{s ? s.label : e.s}</span>
                      <span style={{ color:"var(--ink-4)" }}>:{e.label}</span>
                      <span style={{ color:"var(--ink-3)" }}>→</span>
                      <span style={{ color: idSet[e.t] ? "var(--coral)" : "var(--ink-3)" }}>{t ? t.label : e.t}</span>
                    </div>
                  );
                })}
                {affectedEdges.length > 8 && (
                  <div style={{ padding:"7px 14px", fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-4)" }}>+ {affectedEdges.length - 8} more</div>
                )}
              </div>
            </div>
          )}

          {/* Neighbour nodes that lose at least one connection */}
          {neighbours.length > 0 && (
            <div style={{ margin:"18px 26px 0" }}>
              <div style={{ fontFamily:"JetBrains Mono", fontSize:9.5, letterSpacing:"0.5px", color:"var(--ink-3)", textTransform:"uppercase", marginBottom:8 }}>Connected nodes affected ({neighbours.length})</div>
              <div style={{ display:"flex", flexWrap:"wrap", gap:6 }}>
                {neighbours.map(function(n){
                  return (
                    <span key={n.id} style={{ display:"inline-flex", alignItems:"center", gap:6, padding:"4px 10px", borderRadius:999, background:"var(--panel)", border:"1px solid var(--line-2)", fontSize:11.5, color:"var(--ink-2)" }}>
                      <ListGlyph node={n} size={12} />
                      {n.label}
                    </span>
                  );
                })}
              </div>
            </div>
          )}

          {/* Acknowledgement checkbox */}
          <label style={{ display:"flex", alignItems:"flex-start", gap:10, margin:"18px 26px 0", padding:"12px 14px", border:"1px solid " + (ack ? "var(--coral)" : "var(--line)"), borderRadius:9, background: ack ? "var(--coral-fill)" : "var(--panel)", cursor:"pointer", transition:"all 140ms ease-out" }}>
            <input type="checkbox" checked={ack} onChange={function(e){ setAck(e.target.checked); }} style={{ marginTop:2, accentColor:"var(--coral)", width:14, height:14 }} />
            <span style={{ fontSize:12.5, color:"var(--ink-2)", lineHeight:1.5 }}>
              I understand this severs <strong>{affectedEdges.length}</strong> edge{affectedEdges.length === 1 ? "" : "s"}{neighbours.length > 0 ? <>, affects <strong>{neighbours.length}</strong> connected node{neighbours.length === 1 ? "" : "s"}</> : ""}, and may break downstream computations and rules.
            </span>
          </label>

          {/* Footnote — undoable assurance */}
          <div style={{ margin:"12px 26px 0", padding:"10px 12px", border:"1px dashed var(--line)", borderRadius:8, background:"var(--panel-2)", fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--ink-3)", lineHeight:1.45 }}>
            You can undo this with <strong style={{ color:"var(--ink-2)" }}>⌘Z</strong> within this session — but downstream rules and computations that referenced the deleted entities will need to be revisited before publishing.
          </div>
        </>)}

        {step === 2 && (
          <div style={{ margin:"22px 26px 0" }}>
            {/* Compact recap pill */}
            <div style={{ display:"flex", flexWrap:"wrap", gap:6, alignItems:"center", padding:"10px 14px", background:"var(--panel)", border:"1px solid var(--line)", borderRadius:9, marginBottom:18, fontFamily:"JetBrains Mono", fontSize:11, color:"var(--ink-3)" }}>
              <span style={{ color:"var(--coral)", fontWeight:700 }}>{ids.length}</span><span>node{ids.length === 1 ? "" : "s"}</span>
              <span style={{ color:"var(--ink-4)" }}>·</span>
              <span style={{ color:"var(--coral)", fontWeight:700 }}>{affectedEdges.length}</span><span>edge{affectedEdges.length === 1 ? "" : "s"}</span>
              <span style={{ color:"var(--ink-4)" }}>·</span>
              <span style={{ color:"var(--coral)", fontWeight:700 }}>{totalProps}</span><span>field{totalProps === 1 ? "" : "s"}</span>
              <span style={{ color:"var(--ink-4)" }}>·</span>
              <span style={{ color:"var(--coral)", fontWeight:700 }}>{fmtNum(totalRecords)}</span><span>record{totalRecords === 1 ? "" : "s"}</span>
            </div>

            <div style={{ fontFamily:"JetBrains Mono", fontSize:10.5, letterSpacing:"0.5px", color:"var(--ink-3)", textTransform:"uppercase", marginBottom:6 }}>Type to confirm</div>
            <div style={{ fontSize:13, color:"var(--ink-2)", lineHeight:1.5, marginBottom:10 }}>
              {multi ? (
                <>Type <code style={{ fontFamily:"JetBrains Mono", padding:"2px 6px", background:"var(--coral-fill)", color:"var(--coral)", borderRadius:4, fontWeight:700 }}>DELETE</code> below to confirm this destructive action.</>
              ) : (
                <>Type the node name <code style={{ fontFamily:"JetBrains Mono", padding:"2px 6px", background:"var(--coral-fill)", color:"var(--coral)", borderRadius:4, fontWeight:700 }}>{requiredPhrase}</code> below to confirm.</>
              )}
            </div>
            <input
              autoFocus
              value={typed}
              onChange={function(e){ setTyped(e.target.value); }}
              placeholder={requiredPhrase}
              style={{ width:"100%", padding:"11px 14px", fontSize:14, fontFamily:"JetBrains Mono", border:"1.5px solid " + (typed && typed.trim() !== requiredPhrase ? "var(--coral)" : "var(--line)"), borderRadius:9, background:"var(--panel)", color:"var(--ink)", outline:"none", boxSizing:"border-box", letterSpacing:"0.3px" }}
            />
            {typed && typed.trim() !== requiredPhrase && (
              <div style={{ fontFamily:"JetBrains Mono", fontSize:10.5, color:"var(--coral)", marginTop:6 }}>Doesn't match — type "{requiredPhrase}" exactly.</div>
            )}
          </div>
        )}

        {/* Footer actions */}
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", gap:8, padding:"22px 26px 22px", marginTop:18 }}>
          <button onClick={step === 2 ? function(){ setStep(1); } : onCancel} className="btn-ghost">
            {step === 2 ? "← Back" : "Cancel"}
          </button>
          <div style={{ display:"flex", gap:8 }}>
            {step === 2 && <button onClick={onCancel} className="btn-ghost">Cancel</button>}
            {step === 1 ? (
              <button onClick={function(){ if (ack) setStep(2); }} disabled={!ack}
                className="btn-dark"
                style={{ background: ack ? "var(--coral)" : "transparent", borderColor: ack ? "var(--coral)" : "var(--line)", color: ack ? "var(--bg-canvas)" : "var(--ink-4)", opacity: ack ? 1 : 0.6, cursor: ack ? "pointer" : "not-allowed" }}>
                Continue →
              </button>
            ) : (
              <button onClick={function(){ if (canContinue) onConfirm(); }} disabled={!canContinue}
                className="btn-dark"
                style={{ background: canContinue ? "var(--coral)" : "transparent", borderColor: canContinue ? "var(--coral)" : "var(--line)", color: canContinue ? "var(--bg-canvas)" : "var(--ink-4)", opacity: canContinue ? 1 : 0.6, cursor: canContinue ? "pointer" : "not-allowed" }}>
                Delete {ids.length > 1 ? (ids.length + " nodes") : "node"}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── EDIT MODE — View / Edit segmented toggle + cursor-mode toggle ──────────
// Floats at the bottom-center of the canvas. View/Edit pill on the left; in
// edit mode, a second smaller pill appears to the right with two cursor
// options: "add" (dashed-plus drop cursor, click adds a node) and "select"
// (plain grab, click empty canvas just deselects).
function ViewEditToggle({ editMode, onEnter, onExit, cursorMode, setCursorMode, canUndo, canRedo, onUndo, onRedo, onDuplicate, canDuplicate, onDelete, canDelete }) {
  var seg = function(active){ return {
    display:"inline-flex", alignItems:"center", gap:7,
    padding:"7px 16px", borderRadius:999, border:"none",
    background: active ? "var(--panel)" : "transparent",
    color: active ? "var(--ink-2)" : "var(--ink-4)",
    fontFamily:"JetBrains Mono", fontSize:11, cursor:"pointer",
    letterSpacing:"0.6px", textTransform:"uppercase",
    boxShadow: active ? "0 1px 3px rgba(40,40,20,0.16), 0 0 0 1px var(--line)" : "none",
    fontWeight: active ? 700 : 500,
    transition:"all 160ms ease-out"
  }; };
  var iconSeg = function(active){ return {
    display:"inline-flex", alignItems:"center", justifyContent:"center",
    width:34, height:30, padding:0, borderRadius:999, border:"none",
    background: active ? "var(--panel)" : "transparent",
    color: active ? "var(--ink-2)" : "var(--ink-4)",
    cursor:"pointer",
    boxShadow: active ? "0 1px 3px rgba(40,40,20,0.16), 0 0 0 1px var(--line)" : "none",
    transition:"all 160ms ease-out"
  }; };
  var pill = { display:"inline-flex", padding:3, borderRadius:999, background:"var(--panel-2)", border:"1px solid var(--line)", boxShadow:"0 6px 24px rgba(40,40,20,0.10), 0 1px 2px rgba(40,40,20,0.05)" };
  return (
    <div style={{ position:"absolute", bottom:18, left:"50%", transform:"translateX(-50%)", zIndex:10, display:"inline-flex", gap:8, alignItems:"center" }}>
      {/* View / Edit pill */}
      <div style={pill}>
        <button onClick={onExit} style={seg(!editMode)}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round">
            <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
            <circle cx="12" cy="12" r="3"/>
          </svg>
          View
        </button>
        <button onClick={onEnter} style={seg(editMode)}>
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.9" strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 20h9"/>
            <path d="M16.5 3.5a2.121 2.121 0 1 1 3 3L7 19l-4 1 1-4 12.5-12.5z"/>
          </svg>
          Edit
        </button>
      </div>
      {/* Cursor mode toggle — only in edit mode */}
      {editMode && (
        <div style={pill}>
          <button onClick={function(){ setCursorMode("select"); }} style={iconSeg(cursorMode === "select")} title="Select cursor — click empty canvas to deselect / pan / marquee">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
              <path d="M5 3 L19 11 L13 13 L11 19 Z"/>
            </svg>
          </button>
          <button onClick={function(){ setCursorMode("add"); }} style={iconSeg(cursorMode === "add")} title="Add-node cursor — click empty canvas to drop a node">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round">
              <circle cx="12" cy="12" r="8" strokeDasharray="3 3"/>
              <line x1="12" y1="8" x2="12" y2="16"/>
              <line x1="8" y1="12" x2="16" y2="12"/>
            </svg>
          </button>
        </div>
      )}
      {/* Undo / Redo / Duplicate — only in edit mode */}
      {editMode && (
        <div style={pill}>
          <button onClick={onUndo} disabled={!canUndo} style={Object.assign({}, iconSeg(false), { opacity: canUndo ? 1 : 0.35, cursor: canUndo ? "pointer" : "not-allowed" })} title="Undo (⌘Z)">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="9 14 4 9 9 4"/>
              <path d="M4 9h11a5 5 0 0 1 0 10h-3"/>
            </svg>
          </button>
          <button onClick={onRedo} disabled={!canRedo} style={Object.assign({}, iconSeg(false), { opacity: canRedo ? 1 : 0.35, cursor: canRedo ? "pointer" : "not-allowed" })} title="Redo (⌘⇧Z)">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="15 14 20 9 15 4"/>
              <path d="M20 9H9a5 5 0 0 0 0 10h3"/>
            </svg>
          </button>
          <button onClick={onDuplicate} disabled={!canDuplicate} style={Object.assign({}, iconSeg(false), { opacity: canDuplicate ? 1 : 0.35, cursor: canDuplicate ? "pointer" : "not-allowed" })} title={canDuplicate ? "Duplicate selected (⌘D)" : "Select a node to duplicate"}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
              <rect x="8" y="8" width="12" height="12" rx="2"/>
              <path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/>
            </svg>
          </button>
          <button onClick={onDelete} disabled={!canDelete}
            style={Object.assign({}, iconSeg(false), { opacity: canDelete ? 1 : 0.35, cursor: canDelete ? "pointer" : "not-allowed" })}
            title={canDelete ? "Delete selected (Delete)" : "Select a node to delete"}>
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
              <polyline points="3 6 5 6 21 6"/>
              <path d="M19 6l-1.2 13.2A2 2 0 0 1 15.8 21H8.2a2 2 0 0 1-2-1.8L5 6"/>
              <path d="M10 11v6M14 11v6"/>
              <path d="M9 6V4a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2"/>
            </svg>
          </button>
        </div>
      )}
    </div>
  );
}

// Small confirmation dialog used by edit-mode deletes and the dirty-exit prompt.
function ConfirmDialog({ title, body, confirmLabel, secondaryLabel, danger, onConfirm, onSecondary, onCancel }) {
  return (
    <div onClick={function(e){ if (e.target === e.currentTarget) onCancel(); }}
      style={{ position:"fixed", top:0, left:0, right:0, bottom:0, background:"rgba(0,0,0,0.42)", zIndex:300, display:"flex", alignItems:"center", justifyContent:"center" }}>
      <div style={{ width:"min(92vw, 460px)", background:"var(--bg-canvas)", borderRadius:12, border:"1px solid var(--line)", padding:"22px 24px 18px", boxShadow:"0 32px 80px rgba(0,0,0,0.32)" }}>
        <div style={{ fontFamily:"'Instrument Serif', serif", fontSize:24, color:"var(--ink)", lineHeight:1.15, marginBottom:8 }}>{title}</div>
        <div style={{ fontSize:13, color:"var(--ink-3)", lineHeight:1.55, marginBottom:18 }}>{body}</div>
        <div style={{ display:"flex", justifyContent:"flex-end", gap:8, flexWrap:"wrap" }}>
          <button onClick={onCancel} className="btn-ghost">Cancel</button>
          {secondaryLabel && <button onClick={onSecondary} className="btn-ghost" style={{ border:"1px solid var(--line)", borderRadius:7, padding:"7px 12px" }}>{secondaryLabel}</button>}
          <button onClick={onConfirm} className="btn-dark" style={ danger ? { background:"var(--coral)", borderColor:"var(--coral)" } : undefined }>{confirmLabel}</button>
        </div>
      </div>
    </div>
  );
}

Object.assign(window, { NODES, EDGES, ListGlyph, colorForNode, CAT_META, metricColor });

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
